In the \emph{matrix sensing} or \emph{trace regression} problem, the goal is to estimate a symmetric matrix $\bm{M}$ from $n$ observations  $(y_i,\bm{X}_i) \in \mathbb{R} \times \mathbb{R}^{d\times d}$ such that
\begin{align}
    y_i = \frac{1}{\sqrt{n}}\langle \bm{X}_i, \bm{M} \rangle + \ensuremath{\varepsilon}_i, \addtocounter{equation}{1}\tag{\theequation} \label{matsens}
\end{align}
where $\langle \cdot, \cdot \rangle$ denotes the Frobenius inner product, $\ensuremath{\varepsilon}_i$ is observation noise, and $\bm{M}$ is assumed to be a symmetric positive semidefinite rank $r$ signal matrix of interest with $r$ typically taken to be much smaller than the dimension $d$ (the scaling by $\frac{1}{\sqrt{n}}$ is primarily for theoretical purposes).

Explicitly,  the Matrix LASSO with tuning parameter $\lambda$, denoted $\bm{Z}^{(\lambda)}$, solves the problem
\begin{align}
    \bm{Z}^{(\lambda)} = arg\,min_{\bm{Z} \succcurlyeq 0} g_{\sf cvx}^{(\lambda)}(\bm{Z}) :=  \frac{1}{2} \sum_{i=1}^{n} (y_i - \langle \bm{X}_i, \bm{Z}\rangle/\sqrt{n} )^2 + \lambda \| \bm{Z} \|_*,
\end{align}
where $\|\cdot\|_*$ denotes the nuclear norm on $d\times d$ matrices (here we take any minimizer of the objective function).

Therefore, partially motivated by these findings, in this paper we are interested in answering the following question:
 \begin{quote}
   \emph{What is the asymptotic behavior of $\bm{Z}^{(\lambda)}$ and $\bm{U}^{(0)}$ when $d^2 \gg n \gg d$ with $r$ held fixed?

For two matrices $\bm{U}$ and $\bm{U}'$ of  dimension $d \times r$, we denote $\mathcal{O}_{\bm{U},\bm{U}'}$ via
\begin{align}
    \mathcal{O}_{\bm{U},\bm{U}'} &= arg\,min_{\mathcal{OO}^{\top} = \bm{I}_r} \| \bm{U} \mathcal{O} - \bm{U}' \|_F.
\end{align}

we define the inner product 
\begin{align}
    \langle \bm{Q}_1, \bm{Q}_2 \rangle_{L_2,F} := \int \langle \bm{Q}_1(\bm{G}), \bm{Q}_2(\bm{G}) \rangle d\mathbb{P}(\bm{G}),
\end{align}
where $\mathbb{P}(\bm{G})$ denotes the density with respect to the Gaussian Orthogonal Ensemble.

We also define the matrix denoising hard thresholding counterpart
\begin{align}
    \bm{Z}_{{\sf HT}} := \mathcal{P}_{{\sf rank}-r} \big( \bm{M} + \sigma \bm{H} \big),
\end{align}
where $\mathcal{P}_{{\sf rank}-r}$ simply computes the best rank $r$ approximation to $\bm{M} + \sigma \bm{H}$, which, by the Ekhart-Young Theorem, is equivalent to setting the $d-r$ smallest singular values of $\bm{M} + \sigma \bm{H}$ to zero.

 \label{ass1}
The low-rank matrix $\bm{M}$ satisfies $\bm{M} = \sqrt{d} \bm{V\Lambda V}^{\top}$, where $\bm{\Lambda}$ is a diagonal $r\times r$ matrix of positive eigenvalues of $\bm{M}$ and $\bm{V}$ is a $d \times r$ orthonormal matrix of corresponding eigenvectors.  
The matrix $\bm{\Lambda}$ has smallest eigenvalue $\lambda_r$ that satisfies
\begin{align}
    C_1 \sqrt{r} < \lambda_r/\sigma < C_2 \sqrt{r},
\end{align}
where $C_1$ and $C_2$ are some sufficiently large constants. Furthermore, it holds that $\frac{\|\bm{M}\|}{\lambda_r \sqrt{d}} \leq \kappa$ for some $\kappa = O(1)$.  Finally, it holds that $\sigma \geq \sigma_{\min} > c > 0$.

 \label{thm:mainthm}
Suppose that \cref{ass1,ass2,ass3} hold. 
There exists a constant $C > 0$ depending on our assumptions such that for all $n$ sufficiently large, 
for any $\ensuremath{\varepsilon}> C\exp( - c dr )$, and for any $1-$Lipschitz function $\phi: \mathbb{R}^{d\times d} \to \mathbb{R}$,
\begin{align}
\begin{split}
    \mathbb{P}\bigg\{ &\bigg| \phi\bigg( \frac{1}{\sqrt{dr}}\bm{U}^{(0)} \bm{U}^{(0)\top} \bigg) - \mathbb{E}_{\bm{H}} \phi\big( \frac{1}{\sqrt{dr}}\bm{Z}_{{\sf HT}} \big) \bigg| > \ensuremath{\varepsilon} + C \sigma \sqrt{\frac{r}{\gamma_n}}\bigg\} \\&\leq  
 O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) + \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg); \end{split} \\
 \begin{split}
    \mathbb{P}\bigg\{ &\bigg| \phi\bigg( \frac{1}{\sqrt{dr}}\bm{Z}^{(\lambda)} \bigg) - \mathbb{E}_{\bm{H}} \phi\big( \frac{1}{\sqrt{dr}}\bm{Z}_{{\sf ST}}^{(\lambda)} \big) \bigg| > \ensuremath{\varepsilon} + C \sigma \frac{\sqrt{r}}{\gamma_n}  \bigg\} \\
    &\leq  O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) + \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg) \end{split}
\end{align}
The same result continues to hold if $\bm{Z}^{(\lambda)}$ is replaced with $\bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top}$.

\begin{align}
\begin{split}
    \mathbb{P}\bigg\{ &\bigg| \phi\bigg( \frac{1}{\sqrt{dr}}\bm{U}^{(0)} \bm{U}^{(0)\top} \bigg) - \mathbb{E}_{\bm{H}} \phi\big( \frac{1}{\sqrt{dr}}\bm{Z}_{{\sf HT}} \big) \bigg| > \ensuremath{\varepsilon} + C \sigma \sqrt{\frac{r}{\gamma_n}}\bigg\} \\&\leq  
 O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) + \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg); \end{split} \\
 \begin{split}
    \mathbb{P}\bigg\{ &\bigg| \phi\bigg( \frac{1}{\sqrt{dr}}\bm{Z}^{(\lambda)} \bigg) - \mathbb{E}_{\bm{H}} \phi\big( \frac{1}{\sqrt{dr}}\bm{Z}_{{\sf ST}}^{(\lambda)} \big) \bigg| > \ensuremath{\varepsilon} + C \sigma \frac{\sqrt{r}}{\gamma_n}  \bigg\} \\
    &\leq  O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) + \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg) \end{split}
\end{align}

 \label{cor:maincor}
Consider the asymptotic regime where $d\to\infty$ with $r$ held fixed and $n = n(d)$ satisfies $ d \ll n(d) \ll d^2$.   Let $\{\bm{M}(d)\}_{d=1}^{\infty}$ denote a sequence of rank $r$ signal matrices, and suppose the eigenvalues of $\bm{M}(d)/\sqrt{d}$ converge deterministically to some limits $\lambda_1,\dots,\lambda_r$ satisfying \cref{ass1}.  Suppose further that \cref{ass1,ass2,ass3} are satisfied for all $n$ and $d$, and suppose $\sigma$ is fixed. Let $\bm{Z}^{(\lambda)} = \bm{Z}^{(\lambda)}(d)$ denote the sequence of convex minimizers, and let $\bm{U}^{(0)} = \bm{U}^{(0)}(d)$ be defined similarly.  
Then it holds that 
\begin{align}
  \liminf_{d\to\infty} \frac{\| \bm{Z}^{(\lambda)} - \bm{M}(d) \|_F^2}{ \| \bm{U}^{(0)}\bm{U}^{(0)\top} - \bm{M}(d) \|_F^2} \geq 1, \addtocounter{equation}{1}\tag{\theequation} \label{mse}
\end{align}
where the limit is in probability, the infimum is over the sequence of problem instances, and strict inequality can hold for particular sequences of matrices $\{\bm{M}(d)\}_{d=1}^{\infty}$.

\begin{align}
    \mathcal{E}_{{\sf Good}} &:= \bigg\{ \bigg\| \frac{1}{n} \sum_i \ensuremath{\varepsilon}_i \bm{X}_i \bigg\| \leq 8\sigma \sqrt{\frac{d}{n}}  \bigg\}  \label{concentration} \\
    &\bigcap \bigg\{ (1 - \delta_{2r}) \|\bm{A}\|_F^2 \leq  \|  \mathcal{X}( \bm{A}) \|^2 \leq (1 + \delta_{2r}) \|\bm{A} \|_F^2 \text{ for all matrices $\bm{A}$ of rank at most $2r$}   \bigg\}  \label{rip} \\
    &\bigcap \bigg\{ \bigg\| \frac{1}{n} \sum_{i} \ensuremath{\varepsilon}_i \langle \bm{X}_i , \bm{A} \rangle \bigg\| \leq C \sigma \sqrt{\frac{dr}{n}}\| \bm{A} \|_F  \text{ for all matrices $\bm{A}$ of rank at most $2r$} \bigg\}. \label{rip2}
 \end{align}

 \label{thm:relatecvxncvx}
Let $\bm{Z}^{(\lambda)}$ denote (any) global minimum of $g^{(\lambda)}_{{\sf cvx}}$, and let $\bm{U}^{(\lambda)}$ denote any critical point of $f^{(\lambda)}_{{\sf ncvx}}$ satisfying the first and second-order necessary conditions for a local minimum.  Then under \cref{ass2,ass3}, 
on the event $\mathcal{E}_{{\sf Good}}$ defined in \eqref{egood}, 
\begin{align}
    \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top} &= \bm{Z}^{(\lambda)}.
\end{align}

\label{lem:relatecvxncvx}
   Let $\bm{Z}^{(\lambda)}$ denote the global minimum of $g^{(\lambda)}_{{\sf cvx}}$, and let $\bm{U}^{(\lambda)}$ denote a stationary point of $f^{(\lambda)}_{{\sf ncvx}}$.  Then as long as $\lambda \geq C_4 \sigma \sqrt{d}$, and $ \| \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} - \bm{M} \|_F < \lambda/(2\delta_{2r})$,     on the event $\mathcal{E}_{{\sf Good}}$ it holds that
   \begin{align}
       \bm{U}^{(\lambda)} \bm{ U}^{(\lambda)\top} &= \bm{Z}^{(\lambda)}.
   \end{align}

    First, observe that any  optimizer $\bm{Z}^{(\lambda)}$ of $g^{(\lambda)}_{{\sf cvx}}$ must satisfy the first-order necessary condition
\begin{align}
  \frac{1}{\sqrt{n}} \sum_{i=1}^{n} \bigg( \langle \bm{X}_i, \bm{Z}^{(\lambda)} - \bm{M} \rangle /\sqrt{n} - \ensuremath{\varepsilon}_i \bigg) \bm{X}_i = -\lambda \bm{VV}^{\top} + \bm{W},
\end{align}
where $\bm{Z}^{(\lambda)} = \bm{V} \Sigma \bm{V}^{\top}$, and $\bm{W}$ lies in the tangent space of $\bm{Z}^{(\lambda)}$ and satisfies $\|\bm{W} \| \leq \lambda $.  In addition, from the first-order necessary condition for a stationary point, $\bm{U}^{(\lambda)}$ satisfies
\begin{align}
   \frac{1}{\sqrt{n}} \sum_{i=1}^{n} \bigg( \langle \bm{X}_i, \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} - \bm{M} \rangle/\sqrt{n} - \ensuremath{\varepsilon}_i \bigg) \bm{X}_i \bm{U}^{(\lambda)} + \lambda \bm{U}^{(\lambda)} &= 0. \addtocounter{equation}{1}\tag{\theequation} \label{uncvx}
\end{align}
Denote
\begin{align}
    \bm{N}_{\ensuremath{\varepsilon}} := \frac{1}{\sqrt{n}}\sum_i \ensuremath{\varepsilon}_i \bm{X}_i.
\end{align}
Equation \cref{uncvx} then implies 
\begin{align}
\mathcal{X}^* \mathcal{X}( \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top} - \bm{M} ) - \bm{N}_{\ensuremath{\varepsilon}} &= 
    -\lambda \bm{V}_{\bm{U}} \bm{V}_{\bm{U}}^{\top} + \bm{W}_{U}, \addtocounter{equation}{1}\tag{\theequation} \label{cnvx}
\end{align}
where $\bm{V}_{{\bm{U}}}$ is the orthonormal matrix associated to the column space of $\bm{U}^{{(\lambda)}}$, and $\bm{W}_U$ is orthogonal to $\bm{V}_{{\bm{U}}}$.  Therefore, it suffices to show that $\|\bm{W}_U \| < \lambda$.  
We have that 
\begin{align}
\mathcal{X}^* \mathcal{X} \big( \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top} - \bm{M} \big) - \bm{N}_{\ensuremath{\varepsilon}} &= 
 -\bm{M} + \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} + \bigg( \mathcal{X}^* \mathcal{X} - \mathcal{I} \bigg) \big( \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} - \bm{M}  \big) - \bm{N}_{\ensuremath{\varepsilon}}.
\end{align}
Plugging this identity into \eqref{cnvx} and rearranging yields
\begin{align}
    \bm{M} + \bigg( \mathcal{I} - \mathcal{X}^* \mathcal{X}  \bigg) \big( \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} - \bm{M}  \big) + \bm{N}_{\ensuremath{\varepsilon}} &=  \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} + \lambda \bm{V}_{U} \bm{V}_U^{\top} - \bm{W}_U \\
    &= \bm{V}_{U} \bigg( \Sigma + \lambda \bm{I} \bigg) \bm{V}_U - \bm{W}_U.  
\end{align}
Since $\bm{W}_U$ is orthogonal to $\bm{V}_{\bm{U}}$, the eigenvalues of $\bm{W}_U$ are equal to the bottom $d - r$ eigenvalues of $\bm{V}_U(\Sigma + \lambda \bm{I}) \bm{V}_U^{\top}$. 
Therefore, by Weyl's inequality, for $r < i \leq d$,
\begin{align}
    \sigma_i \bigg( \bm{V}_{U} \bigg( \Sigma + \lambda \bm{I} \bigg) \bm{V}_U^{\top} - \bm{W}_U \bigg) &\leq \sigma_i(\bm{M}) + \bigg\| \bigg( \mathcal{I} - \mathcal{X}^* \mathcal{X}  \bigg) \big( \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} - \bm{M}  \big) + \bm{N}_{\ensuremath{\varepsilon}} \bigg\| \\
    &\leq \bigg\|  \bigg( \mathcal{I} - \mathcal{X}^* \mathcal{X}  \bigg) \big( \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} - \bm{M}  \big) \bigg\| + \bigg\| \bm{N}_{\ensuremath{\varepsilon}} \bigg\| \\
    &\leq  \delta_{2r} \| \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} - \bm{M} \|_F + \| \bm{N}_{\ensuremath{\varepsilon}} \| \\
    &< \frac{\lambda}{2} + \frac{\lambda}{2} \\
    &< \lambda,
\end{align}
since by \cref{ass3} $\lambda$ is taken to be  larger than $C_4 \sigma \sqrt{d}$, since then on $\mathcal{E}_{{\sf Good}}$ it holds that $\|\bm{N}_{\ensuremath{\varepsilon}}\| \leq C\sigma \sqrt{d} < \frac{C_4 \sigma \sqrt{d}}{2}$, and  $ \| \bm{U}^{(\lambda)}\bm{U}^{(\lambda)\top} - \bm{M} \|_F < \lambda/(2\delta_{2r})$ by  assumption.  Thus, we have shown that $\| \bm{W}_U\| < \lambda$, which completes the proof.

 \label{lem:uncvxgood}
Let $\bm{U}^{(\lambda)}$ be a minimizer of $f^{(\lambda)}_{{\sf ncvx}}$ satisfying the second-order necessary condition.  Then on the event $\mathcal{E}_{{\sf Good}}$ it holds that
\begin{align}
    \frac{1}{\sqrt{dr}}\| \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top} - \bm{M} \|_F &\leq C \sigma. 
\end{align}
In particular, under \cref{ass2} and \cref{ass3} the conditions of \cref{lem:relatecvxncvx} hold.

 \label{thm:matrixcgmt}
Let $\mathcal{A}: \mathbb{R}^{d \times d} \to \mathbb{R}^{n}$ be an operator such that $\mathcal{A}( \bm{M})_i =\langle \bm{A}_i, \bm{M} \rangle $, where each $\bm{A}_i$ is a GOE matrix. Let $\bm{H} \in \mathbb{R}^{d\times d}$ be a GOE matrix, and let $\bm{g}$ be a standard $n$-dimensional Gaussian random vector.  Let $\mathcal{S}_{\bm{W}} \in \mathbb{R}^{d\times d}$ and $\mathcal{S}_{\bm{\nu}} \in \mathbb{R}^{n}$ be compact sets, and let $\psi: \mathcal{S}_{\bm{W}} \times \mathcal{S}_{\bm{\nu}} \to \mathbb{R}$ be a continuous function.  Define
\begin{align}
    \Phi(\mathcal{A}) :&= \min_{\bm{W}\in \mathcal{S}_{\bm{W}}} \max_{\bm{\nu} \in \mathcal{S}_{\bm{\nu}}} \langle \mathcal{A}[ \bm{W}], \bm{\nu} \rangle  + \psi(\bm{W}, \bm{\nu}); \\
    \phi(\bm{g},\bm{H}) :&= \min_{\bm{W}\in \mathcal{S}_{\bm{W}}} \max_{\bm{\nu} \in \mathcal{S}_{\bm{\nu}}} \| \bm{W} \|_F \langle \bm{g}, \bm{\nu} \rangle  + \| \bm{\nu}\| \langle \bm{H}, \bm{W} \rangle + \psi(\bm{W}, \bm{\nu}).
\end{align}
Then it holds that
\begin{align}
    \mathbb{P}\bigg(  \Phi(\mathcal{A})  \leq  t \bigg) \leq 2 \mathbb{P} \bigg(  \phi(\bm{g,H})  \leq t\bigg). 
\end{align}
If in addition both $\mathcal{S}_{\bm{W}}$ and $\mathcal{S}_{\bm{\nu}}$ are convex and $\psi(\bm{W},\bm{\nu})$ is convex-concave, then
\begin{align}
    \mathbb{P}\bigg(  \Phi(\mathcal{A})  \geq  t \bigg) \leq 2 \mathbb{P} \bigg(  \phi(\bm{g,H})  \geq t\bigg). 
\end{align}

\label{lem:saddlepoint}
Define the system of equations
\begin{subequations}
\label{fxdpt}
 \begin{align}
    \tau^2 &= \sigma^2 + \frac{dr}{n} {\sf R}_{\lambda}\big( \tau^2, \zeta); \label{fxtpt1} \\
    \zeta &=1 -  \frac{{\sf df}_{\lambda}\big( \tau^2,\zeta)}{n},  \addtocounter{equation}{1}\tag{\theequation} \label{fxdpt2}
\end{align}
\end{subequations}
where  
\begin{align}
    {\sf R}_{\lambda}(\tau^2,\zeta) :&=  \frac{1}{dr} \mathbb{E} \bigg[ \big\| \bm{ Z}_{\sf ST}^{(\lambda/\zeta)}(\tau) - \bm{M} \|_F^2 \bigg ];  \\ 
    {\sf df}_{\lambda}(\tau^2,\zeta) &= \frac{1}{\tau} \mathbb{E} \bigg\langle \bm{H} ,  \bm{ Z}_{\sf ST}^{(\lambda/\zeta)}(\tau) \bigg\rangle 
\end{align}
where the expectation is with respect to $\bm{H} \sim {\sf GOE}(d)$.   Let $\tau^*$ and $\beta^* = \zeta^* \tau^*$ be such that $(\tau^*,\zeta^*)$ satisfy the system of equations \eqref{fxdpt}.  Then it holds that $L^{*}_{\lambda} = \psi^{*}_{\lambda}(\tau^*,\beta^*)$.

\begin{align}
    {\sf R}_{\lambda}(\tau^2,\zeta) :&=  \frac{1}{dr} \mathbb{E} \bigg[ \big\| \bm{ Z}_{\sf ST}^{(\lambda/\zeta)}(\tau) - \bm{M} \|_F^2 \bigg ];  \\ 
    {\sf df}_{\lambda}(\tau^2,\zeta) &= \frac{1}{\tau} \mathbb{E} \bigg\langle \bm{H} ,  \bm{ Z}_{\sf ST}^{(\lambda/\zeta)}(\tau) \bigg\rangle 
\end{align}

\label{lem:fxdpointprops}
Suppose that \cref{ass1,ass2,ass3} are satisfied.  Then it holds that $\sigma \leq \tau^* \leq C \sigma$ and 
\begin{align}
    |(\tau^*)^2 - \sigma^2 | =O\bigg( \frac{d r}{n} \sigma^2 \bigg); \qquad |\zeta^* - 1 | = O\bigg( \frac{d r^{3/2}}{n} \bigg),
\end{align}
where the implicit constants depend on the constants in our assumptions.

\label{lem:ZSTtau} Suppose that \cref{ass1,ass2,ass3} are satisfied. Then for any $1$-Lipschitz function $\phi: \mathbb{R}^{d\times d} \to \mathbb{R}$ it holds that
    \begin{align}
         \bigg| \mathbb{E} \phi \big( \bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)/\sqrt{dr} \big) - \mathbb{E} \phi \big( \bm{Z}_{{\sf ST}}^{(\lambda)}/\sqrt{dr} \big) \bigg| = O\bigg( \sigma \frac{d r^{3/2}}{n}\bigg).
    \end{align}


 \label{thm:cvxasymptotics}
Suppose that \cref{ass1,ass2,ass3} are satisfied. Then for any 1-Lipschitz function $\phi: \mathbb{R}^{d \times d} \to \mathbb{R}$ and for any $\ensuremath{\varepsilon}$ satisfying $\ensuremath{\varepsilon} > C \exp( - c d r)$, it holds that
\begin{align}
   \mathbb{P}\bigg\{ &\bigg| \phi\bigg( \frac{1}{\sqrt{dr}} \bm{U}^{(\lambda) } \bm{U^}{(\lambda)\top} \bigg) - \mathbb{E}_{\bm{H}} \phi\bigg( \frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda/\zeta^*)}_{{\sf ST}}(\tau^*) \bigg) \bigg| > \ensuremath{\varepsilon} \bigg\}\\
   &\leq  O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) - \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg),
\end{align}
where the constants depend on problem parameters.  The same result holds if $\bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top}$ is replaced with $\bm{Z}^{(\lambda)}$.

\begin{align}
   \mathbb{P}\bigg\{ &\bigg| \phi\bigg( \frac{1}{\sqrt{dr}} \bm{U}^{(\lambda) } \bm{U^}{(\lambda)\top} \bigg) - \mathbb{E}_{\bm{H}} \phi\bigg( \frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda/\zeta^*)}_{{\sf ST}}(\tau^*) \bigg) \bigg| > \ensuremath{\varepsilon} \bigg\}\\
   &\leq  O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) - \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg),
\end{align}

    The high-level strategy will be to argue that any minimizer of $C_{\lambda}^{(n)}(\bm{W})$ over the shifted positive semidefinite cone $\{\bm{W}: \bm{W} + \bm{M} \succcurlyeq 0 \}$ must be within $\ensuremath{\varepsilon} \sqrt{dr}$ of $\bm{ Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)$ with high probability.  
Let $\bm{\widehat W} := \bm{ Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)- \bm{M}$, and let $\phi$ be a fixed 1-Lipschitz function. Consider the set $\mathcal{D}$ defined via
\begin{align}
    \mathcal{D} := \bigg\{ \bm{W} :\bigg| \phi\bigg( \frac{\bm{W} + \bm{M}}{\sqrt{dr}}\bigg) - \mathbb{E} \phi\bigg( \frac{\bm{\widehat W} + \bm{M}}{\sqrt{dr}} \bigg) \bigg|\leq \frac{\ensuremath{\varepsilon}}{2} \bigg\} \cap \bigg\{ \bm{W} + \bm{M} \succcurlyeq 0 \bigg\},
\end{align}
and let $\mathcal{D}_{\ensuremath{\varepsilon}}$ denote the $\ensuremath{\varepsilon}$-enlargement of the set $\mathcal{D}$; i.e. $\mathcal{D}_{\ensuremath{\varepsilon}} := \{ \bm{V} = \bm{W} + \bm{W}': \| \bm{W}' \|_F \leq \ensuremath{\varepsilon}, \bm{W} \in \mathcal{D}\}$.  Since by the proof of \cref{thm:relatecvxncvx} $\bm{Z}^{(\lambda)}$ is rank at most $r$ and within radius $R = C \sigma \sqrt{dr}$ of $\bm{M}$ with high probability, we will show that any rank at most $r$ minimum of $C^{(n)}_{\lambda}$ on $\mathcal{D}_{\ensuremath{\varepsilon}/2}^c$ (outside of the $\ensuremath{\varepsilon}/2$ ball) but within radius $R$ of $\bm{M}$ must be suboptimal with high probability, which will imply that the minimizer must lie within $\mathcal{D}_{\ensuremath{\varepsilon}/2}$ with high probability. 


Carrying out this argument, in our full proof of \cref{thm:cvxasymptotics} in \cref{sec:step1}, we show via the Matrix CGMT that it holds that
\begin{align}
    \mathbb{P}\bigg\{ arg\,min ~ &C^{(n)}_{\lambda}(\bm{W}) \notin \mathcal{D}_{\ensuremath{\varepsilon}/2} \bigg\} \\
    &\leq 2 \mathbb{P}\bigg\{ \bm{\widehat W} \notin \mathcal{D} \bigg\}+ 2 \mathbb{P}\bigg\{ L_{\lambda}^{(n)}( \mathbb{R}^{d\times d}) \geq L_{\lambda}^* + C \ensuremath{\varepsilon}^2 \bigg\} \\
    &+ 2 \mathbb{P}\bigg\{ L_{\lambda}^{(n)}\bigg( \mathbb{B}_{\ensuremath{\varepsilon}/2}^c(\bm{\widehat W}/\sqrt{dr}) \cap \{\mathrm{rank}(\bm{W + M}) \leq r \} \cap \{\| \bm{W}\|_F \leq R\} \bigg)  \leq L_{\lambda}^* + C \ensuremath{\varepsilon}^2 \bigg\},
\end{align}
where $L_{\lambda}^*$ is the quantity defined in the previous subsection. Therefore, the proof boils down to analyzing the three terms on the right hand side above. It turns out that the first two terms are straightforward to bound: the first term is exponentially small as $\bm{Z}^{(\lambda/\zeta^*)}_{{\sf ST}}(\tau^*)$ is a proximal operator and hence Lipschitz.  The second term is also well-behaved as $L_{\lambda}^{(n)}$ is expected to concentrate about $L_{\lambda}^*$  at its global minimum.

The final remaining quantity is significantly more difficult to analyze.  The term inside the probability can be understood as the minimum of value of $L_{\lambda}^{(n)}$ over the set of matrices $\bm{W}$ such that:
\begin{enumerate}
    \item  They are at least $\ensuremath{\varepsilon}/2$ distance away from $\bm{\widehat W}$;
    \item $\bm{W} + \bm{M}$ is rank at most $r$;
    \item $\bm{W}$ has norm at most $R$.
\end{enumerate}
In order to analyze the function $L_{\lambda}^{(n)}$ over matrices such that $\mathrm{rank}(\bm{W} + \bm{M}) \leq r $, we define the auxiliary function
\begin{align}
    h(\bm{U}) &= \frac{\gamma_n}{2} \bigg( \sqrt{\frac{\|\bm{UU}^{\top} - \bm{M}\|_F^2}{n} + \sigma^2} \frac{\|\bm{g}\|}{\sqrt{n}} - \frac{\langle \bm{H}, \bm{UU}^{\top} - \bm{M}\rangle}{n} \bigg)_+^2 + \frac{\lambda}{dr} \big\{ \| \bm{U}\|_F^2 - \|\bm{M}\|_* \big\}.
\end{align}
It is straightforward to see that if $\bm{W} = \bm{UU}^{\top} - \bm{M}$, then $h(\bm{U}) = L_{\lambda}^{(n)}(\bm{W})$.  Therefore, analyzing $L_{\lambda}^{(n)}$ over rank at most $r$ matrices is equivalent to analyzing the function $h(\bm{U})$ over $\mathbb{R}^{d \times r}$.   Intuitively, since  $L_{\lambda}^{(n)}(\mathbb{R}^{d \times d})$ is close to $L_{\lambda}^*$, the optimization geometry of $L_{\lambda}^{(n)}$ should be similar to that of matrix soft-thresholding.  Therefore, since $h(\bm{U})$ is the ``nonconvex version'' of $L_{\lambda}^{(n)}$, the geometry of $h(\bm{U})$ should behave similarly to that of nonconvex matrix factorization.  

Carrying out this intuition, in \cref{lem:hstronglyconvex} we show that the function $h(\bm{U})$ is strongly convex on an appropriate high-probability event $\mathcal{E}_h$ within a region $\mathcal{R} \subset \mathbb{R}^{d \times r}$ defined via
\begin{align}
    \mathcal{R} := \bigg\{ \bm{U}: \| \bm{U} - \bm{U}^* \mathcal{O}_{\bm{U}^*,\bm{U}} \| \leq \frac{c}{\kappa} \| \bm{U}^* \| \bigg\},
\end{align}
where $c$ is some universal constant, $\bm{U}^*$ is such that $\bm{M}  = \bm{U}^* \bm{U}^{*\top}$, and $\mathcal{O}_{\bm{U}^*,\bm{U}} $ is the Frobenius-optimal orthogonal matrix aligning $\bm{U}$ and $\bm{U}^*$.  This argument is significantly different from previous analyses for the LASSO, in which the analogue of $L_{\lambda}^{(n)}$ is already strongly convex in a region near its optimal value \citep{miolane_distribution_2021}.  In contrast, in our setting the function $L_{\lambda}^{(n)}$ need not be strongly convex near $\bm{\widehat W}$, but $h(\bm{U})$ can be shown to be (near $\bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)$).  This discrepancy is due to the fact that $\langle \bm{H},\bm{W} \rangle$ does not concentrate at rate $O(\sqrt{dr} \|\bm{W}\|_F)$ uniformly over all matrices $\bm{W}$ (which is what is required on the event $\mathcal{E}_h$ for strong convexity), but $\langle \bm{H}, \bm{UU}^{\top} - \bm{M} \rangle$ does concentrate at this rate uniformly over all matrices $\bm{U}$.  


We then demonstrate that when $\|\bm{UU}^{\top} - \bm{M} \|_F \leq R$, then this automatically implies that $\bm{U} \in \mathcal{R}$. Consequently, by strong convexity, we show that there is a high-probability event $\mathcal{E}_{{\sf ST}}$ (depending only on $\bm{Z}^{(\lambda/\zeta^*)}(\tau^*)$) such that if
\begin{align}
    \frac{\|\bm{UU}^{\top} - \bm{Z}^{(\lambda/\zeta^*)}(\tau^*)\|_F}{\sqrt{dr}} > \frac{\ensuremath{\varepsilon}}{2},
\end{align}
then $\bm{U}$ must satisfy 
\begin{align}
    h(\bm{U}) > \min_{\bm{U}: \|\bm{U}- \bm{U}^* \mathcal{O}_{\bm{U}^*,\bm{U}} \|_F \leq \frac{R}{8 \|\bm{U}^*\|}} h(\bm{U}) + C\ensuremath{\varepsilon}^2,
\end{align}
where $C$ is some universal constant.   The above display turns out to be equivalent to the expression
\begin{align}
    L_{\lambda}^{(n)}\bigg( \mathbb{B}_{\ensuremath{\varepsilon}/2}^c(\bm{\widehat W}/\sqrt{dr}) \cap \mathrm{rank}(\bm{W} + \bm{M}) \leq r \cap \{ \|\bm{W}\|_F \leq R \} \bigg) > L_{\lambda}^* + C \ensuremath{\varepsilon}^2,
\end{align}
which occurs on the event $\mathcal{E}_h \cap \mathcal{E}_{{\sf ST}}$.  Therefore, the proof is completed by tabulating the probabilities of these events.

