        \bm{Z}_{{\sf deb}}^{(\lambda)} &= \bm{V}_{U} \big( \bm{ \Sigma}+ \lambda \bm{I} \big) \bm{V}_U^{\top}, \label{eq:zdebidentity1}
    \end{align}
    where $\bm{V}_U \bm{\Sigma}^{1/2} \bm{W}_U^{\top}$ is the singular value decomposition of $\bm{U}^{(\lambda)}$.   Furthermore, on this same event it holds that 
\begin{align}
    \bm{U}_{{\sf deb}}^{(\lambda)} \bm{U}_{{\sf deb}}^{(\lambda)\top} &= \bm{Z}_{{\sf deb}}^{(\lambda)}. \label{eq:zdebidentity2}
    \end{align}

    Observe that from \cref{thm:relatecvxncvx}, on the event $\mathcal{E}_{{\sf Good}}$ it holds that $\bm{Z}^{(\lambda)} = \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top}$ under \cref{ass2,ass3}. Furthermore, from the proof of \cref{thm:relatecvxncvx}  we have that
    \begin{align}
        \mathcal{X}^* \mathcal{X} \big( \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top} - \bm{M} \big) - \bm{N}_{\ensuremath{\varepsilon}} = - \lambda \bm{V}_U \bm{V}_U^{\top} + \bm{W},
    \end{align}
    where $\bm{W}$ is orthogonal to $\bm{V}_U$ and has spectral norm bounded by $\lambda$.  Therefore, we have that
\begin{align}
    \bm{Z}^{(\lambda)} + \frac{1}{n} \sum_{i=1}^{n} \bigg( y_i - \langle \bm{X}_i , \bm{Z}^{(\lambda)} \rangle \bigg) \bm{X}_i &= \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top} + \mathcal{X}^* \mathcal{X} \big( \bm{M} - \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top} \big) + \bm{N}_{\ensuremath{\varepsilon}} \\
    &= \bm{U}^{(\lambda)} \bm{U}^{(\lambda)\top} + \lambda \bm{V}_U \bm{V}_U^{\top} - \bm{W} \\
    &= \bm{V}_U \big( \bm{\Sigma} + \lambda \bm{I}  \big) \bm{V}_U^{\top} - \bm{W},
\end{align}
where the final equality is due to the fact that $\bm{U}^{(\lambda)}$ has singular vectors $\bm{V}_U$.  After taking the rank $r$ projection and recognizing that the singular values of the matrix $\bm{V}_U \big( \bm{\Sigma} + \lambda \bm{I} \big) \bm{V}_U^{\top}$ are strictly larger than $\lambda$, we obtain that
\begin{align}
    \bm{Z}^{(\lambda)}_{{\sf deb}} &= \bm{V}_U \big( \bm{\Sigma} + \lambda \bm{I} \big) \bm{V}_U^{\top},
\end{align}
which proves \eqref{eq:zdebidentity1}.
Furthermore, if $\bm{U}^{(\lambda)} = \bm{V}_U \bm{\Sigma}^{1/2} \bm{W}_U^{\top}$, then
    \begin{align}
        \bm{U}^{(\lambda)}_{{\sf deb}} \bm{U}^{(\lambda)\top}_{{\sf deb}} &= \bm{U}^{(\lambda)} \bigg( \bm{I} + \lambda \big( \bm{U}^{(\lambda)\top} \bm{U}^{(\lambda)} \big)^{-1} \bigg)  \bm{U}^{(\lambda)\top} \\
        &= \bm{V}_U \bm{\Sigma}^{1/2} \bm{W}_U^{\top} \bigg(   \bm{I} + \lambda \bm{W}_U \bm{\Sigma}^{-1} \bm{W}_U^{\top} \bigg) \bm{W}_U \bm{\Sigma}^{1/2} \bm{V}_U^{\top} \\
        &= \bm{V}_U \big( \bm{\Sigma} + \lambda \bm{I}\big) \bm{V}_U^{\top},
     \end{align}
     which proves \eqref{eq:zdebidentity2}.

