We will argue that $\phi\big( \frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda)}_{{\sf deb}} \big)$ is a Lipschitz function of $\bm{Z}^{(\lambda)}$ on the event $\mathcal{E}_{{\sf Good}}$. Indeed, on this event, by the proof of \cref{thm:relatecvxncvx}, it holds that $\|\bm{Z}^{(\lambda)} - \bm{M} \|_F\leq C \sigma \sqrt{dr}$. From the condition $\lambda_{\min}(\bm{M}) \geq C_0 \sigma \sqrt{dr}$,  Weyl's inequality implies that
\begin{align}
\lambda_r(\bm{Z}^{(\lambda)}) \geq \lambda_r(\bm{M}) - C \sigma \sqrt{dr} \geq (C_0 - C) \sigma \sqrt{dr} \geq \lambda \sqrt{r},
\end{align}
provided that $C_0$ is sufficiently large.  From \cref{thm:udebzdeb}, on the event $\mathcal{E}_{{\sf Good}}$ it holds that $\bm{Z}^{(\lambda)}_{{\sf deb}} = \bm{V}_U \big( \Sigma + \lambda \bm{I} \big) \bm{V}_U^{\top}$, where $\bm{V}_U$ are the leading $r$ eigenvectors of $\bm{Z}^{(\lambda)}$.  Let $\eta$ denote the function which takes a matrix and adds $\lambda/\sqrt{dr}$ to the leading $r$ eigenvalues of a matrix.  Then since $\bm{Z}^{(\lambda)} = \bm{V}_U \bm{\Sigma} \bm{V}_U^{\top}$,
\begin{align}
    \eta( \bm{Z}^{(\lambda)}/\sqrt{dr}) = \frac{1}{\sqrt{dr}}\bm{V}_U \big(  \bm{\Sigma} + \lambda \bm{I} \big) \bm{V}_U^{\top} = \bm{Z}^{(\lambda)}_{{\sf deb}}/\sqrt{dr},
\end{align}
so that $\eta(\bm{Z}^{(\lambda)}/\sqrt{dr}) = \bm{Z}_{{\sf deb}}^{(\lambda)}/\sqrt{dr}$.  We claim that $\eta $ is Lipschitz on the set
\begin{align}
  \mathcal{S} :=  \{\bm{A} \in\mathbb{R}^{d\times d} : \lambda_{r+1}(\bm{A}) =0; \lambda_{r}(\bm{A}) \geq \frac{\lambda}{\sqrt{d}}\},
\end{align}
which contains $\bm{Z}^{(\lambda)}/\sqrt{dr}$ on the event $\mathcal{E}_{{\sf Good}}$.  
To see that $\eta$ is Lipschitz, suppose that $\bm{A}$ and $\bm{B}$ are two matrices in $\mathcal{S}$, and let them have eigendecompositions $\bm{U}_A \bm{\Sigma}_A \bm{U}_A^{\top}$ and $\bm{U}_B \bm{\Sigma}_B \bm{U}_B^{\top}$ respectively.  First, if $\|\bm{A} - \bm{B} \|_F < \lambda/\sqrt{d}$, then
\begin{align}
    \| \eta (\bm{A} ) - \eta (\bm{B}) \|_F &= \| \bm{U}_A (\bm{\Sigma} + \frac{\lambda}{\sqrt{dr}}\bm{I}) \bm{U}_A^{\top} - \bm{U}_B ( \bm{\Sigma}_B + \frac{\lambda}{\sqrt{dr}} \bm{I}) \bm{U}_B^{\top} \|_F \\
    &\leq \| \bm{A} - \bm{B} \|_F +\frac{\lambda}{\sqrt{dr}} \| \bm{U}_A \bm{U}_A^{\top} - \bm{U}_B \bm{U}_B^{\top} \|_F \\
    &\leq \| \bm{A} - \bm{B}\|_F +\frac{\lambda}{\sqrt{dr}}\frac{\|\bm{A} - \bm{B}\|_F}{\frac{\lambda}{\sqrt{d}}} \\
    &\leq 2 \| \bm{A} - \bm{B}\|_F,
\end{align}
where we have used the Davis-Kahan Theorem.  On the other hand, if $\|\bm{A} - \bm{B}\|_F \geq \lambda/\sqrt{d}$, then
\begin{align}
     \| \eta (\bm{A} ) - \eta (\bm{B}) \|_F &\leq \| \bm{A} - \bm{B}\|_F + \frac{\lambda}{\sqrt{dr}} \| \bm{U}_A \bm{U}_A^{\top} - \bm{U}_B \bm{U}_B^{\top} \|_F \\
     &\leq \| \bm{A} - \bm{B}\|_F + \frac{1}{\sqrt{r}} \| \bm{A} - \bm{B}\|_F \| \bm{U}_A \bm{U}_A^{\top} - \bm{U}_B \bm{U}_B^{\top} \|_F \\
     &\leq 3 \| \bm{A} - \bm{B} \|_F,
\end{align}
since the Frobenius norm of the difference of projection matrices is always at most $\sqrt{2r}$.  Consequently, $\eta$ is at most a $3$-Lipschitz function on this set.  By Kirszbaum's theorem, there exists a Lipschitz extension $\widetilde \eta : \mathbb{R}^{d\times d} \to \mathbb{R}^{d\times d}$ such that $\widetilde \eta $ has the same Lipschitz constant of $\eta $ and $\widetilde \eta |_{\mathcal{S}} = \eta$.  In particular, on the event $\mathcal{E}_{{\sf Good}}$, $\eta $ and $\widetilde \eta$ coincide.  Let $\phi$ be any Lipschitz function, and let $\widetilde \phi = \phi \circ \widetilde \eta$, which is also Lipschitz.  By \cref{thm:cvxasymptotics},
\begin{align}
    \mathbb{P}\bigg\{  \phi \bigg( &\frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda)}_{{\sf deb}} \bigg) - \mathbb{E} \phi \bigg( \frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda/\zeta^*)}_{{\sf ST}}(\tau^*) \bigg) > \ensuremath{\varepsilon} \bigg\} \\
    &\leq  \mathbb{P}\bigg\{  \phi \bigg( \frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda)}_{{\sf deb}} \bigg) - \mathbb{E} \phi \bigg( \frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda/\zeta^*)}_{{\sf ST}}(\tau^*) \bigg) > \ensuremath{\varepsilon} \bigg\} \cap \mathcal{E}_{{\sf Good}} + \mathbb{P} \mathcal{E}_{{\sf Good}}^c \\
    &\leq \mathbb{P}\bigg\{ \widetilde \phi \bigg( \frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda)} \bigg) - \mathbb{E} \widetilde \phi \bigg( \frac{1}{\sqrt{dr}} \bm{Z}^{(\lambda/\zeta^*)}_{{\sf ST}}(\tau^*) \bigg) > \ensuremath{\varepsilon} \bigg\} + \mathbb{P} \mathcal{E}_{{\sf Good}}^c \\
    &\leq   O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) - \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg),
\end{align}
which completes the proof.

