To prove existence and uniqueness of $\tau^*,\zeta^*$, we follow the argument of Lemma A.2 of \citet{celentano_lasso_2023}.  Define functions $\mathcal{T}, \mathcal{Z} : L^2( \mathbb{R}^{d\times d} ; \mathbb{R}^{d \times d} ) \to \mathbb{R}$ via
\begin{align}
    \mathcal{T}(\bm{Z}) := \sigma^2 + \frac{\| \bm{Z} - \bm{M} \|_{L^2,F}^2}{n}, \\
    \mathcal{Z}(\bm{Z}) :=  \bigg( 1 - \frac{\langle \bm{H}, \bm{Z} \rangle_{L^2,F} }{n \mathcal{T}(\bm{Z})} \bigg)_+.
\end{align}
Define the function $\mathcal{E} : L^2(  \mathbb{R}^{d\times d} \times \mathbb{R}^{d \times d} ) \to \mathbb{R}$ via 
\begin{align}
\mathcal{E}(\bm{Z}) := \frac{1}{2} \bigg( \sqrt{\sigma^2 + \frac{\|\bm{Z - M}\|_{L^2,F}^2}{n}} - \frac{\langle \bm{H}, \bm{Z - M} \rangle_{L^2,F}}{n} \bigg)^2_+ + \frac{\lambda}{n} \mathbb{E} \big\{ \| \bm{Z}  \|_* - \| \bm{M} \|_* \big\},
\end{align}
where we note that $\bm{Z}$ is viewed as a function  $\mathbb{R}^{d\times d} \to \mathbb{R}^{d\times d}_{\succcurlyeq 0}$ in $L^{2,F}(\mathbb{R}^{d\times d})$.  
\\ \ \\
\noindent
\textbf{Step 1: Showing $\mathcal{E}(\bm{Z})$ has minimizers.} 
 We will show that $\mathcal{E}(\bm{Z}) \to \infty$ as $\| \bm{Z} \|_{L^2,F} \to \infty$, whence $\mathcal{E}(\bm{Z})$ has a minimizer.  
To wit, we note that
\begin{align}
\frac{\lambda}{n} \mathbb{E} \| \bm{Z} \|_* - \| \bm{M} \|_* &\geq \frac{\lambda}{n} \mathbb{E} \| \bm{Z} - \bm{M} \|_F - 2\| \bm{M} \|_*,
\end{align}
which holds from the standard inequality $\| \bm{Z} \|_* \geq \| \bm{Z} \|_F$.  In addition, for any $M > 0$, it holds that
\begin{align}
     | \langle \bm{Z} - \bm{M}, \bm{H} \rangle | &= \big| \mathbb{E} \langle \bm{Z}(\bm{H}) - \bm{M}, \bm{H} \mathbb{I}_{\| \bm{H} \|_F > M } \rangle_{L^2,F} + \mathbb{E} \langle \bm{Z}(\bm{H}) - \bm{M}, \bm{H} \rangle_{L^2_F} \mathbb{I}_{\| \bm{H} \|_F \leq M} \big| \\
     &\leq \| \bm{Z}- \bm{M} \|_{L^2,F} (\mathbb{E} \| \bm{H} \|_F^2 \mathbb{I}_{\| \bm{H} \|_F > M} )^{1/2} + M \mathbb{E} \| \bm{Z}(\bm{H}) - \bm{M} \|_F.
\end{align}
Let $M$ be sufficiently large such that $(\mathbb{E} \| \bm{H} \|_F^2 \mathbb{I}_{\| \bm{H} \|_F > M} )^{1/2} < \sqrt{n}/2.$  Then
\begin{align}
    \mathcal{E}(\bm{Z}) &\geq \frac{1}{2} \bigg( \frac{\| \bm{Z} - \bm{M} \|_{L^2,F}}{2\sqrt{n}} - \frac{M}{n} \mathbb{E} \| \bm{Z}(\bm{H}) - \bm{M}\|_F \bigg)^2_+ +\frac{\lambda}{n} \mathbb{E} \| \bm{Z} - \bm{M} \|_F - 2\frac{\lambda}{n}\| \bm{M} \|_*.
\end{align}
We now analyze three cases:
\begin{itemize}
    \item \textbf{Case 1: $\|\bm{Z} - \bm{M} \|_{L^2,F}/(2\sqrt{n}) \leq M \mathbb{E} \| \bm{Z}(\bm{H}) - \bm{M} \|_F/n$}.  In this case, the term inside the parentheses is zero, and it holds that
    \begin{align}
        \frac{\lambda}{n} \mathbb{E} \| \bm{Z} - \bm{M} \|_F \geq \frac{\lambda}{2 M \sqrt{n}} \| \bm{Z} - \bm{M} \|_{L^2,F}.
    \end{align}
    \item \textbf{Case 2: $\| \bm{Z} - \bm{M} \|_{L^2,F}/(4/\sqrt{n}) \leq M\mathbb{E} \| \bm{Z}(\bm{H}) - \bm{M} \|_F/n <  \|\bm{Z} - \bm{M} \|_{L^2,F}/(2\sqrt{n})$}. In this case, we have that
    \begin{align}
        \frac{1}{2} \bigg( \frac{\|\bm{Z} - \bm{M} \|_{L^2,F}}{2\sqrt{n}} - \frac{M}{n} \mathbb{E} \| \bm{Z} - \bm{M} \|_F \bigg)^2_+ &\geq \frac{1}{2} \bigg( \frac{\|\bm{Z} - \bm{M}\|_{L^2,F}}{4 \sqrt{n}} \bigg)^2 \geq \frac{\|\bm{Z} - \bm{M}\|_{L^2,F^2}^2}{32 n}
    \end{align}
    \item \textbf{Case 3: $\| \bm{Z} - \bm{M} \|_{L^2,F}/(4/\sqrt{n}) >  M\mathbb{E} \| \bm{Z}(\bm{H}) - \bm{M} \|_F/n$ }.  In this case we again have the bound 
      \begin{align}
        \frac{1}{2} \bigg( \frac{\|\bm{Z} - \bm{M} \|_{L^2,F}}{2\sqrt{n}} - \frac{M}{n} \mathbb{E} \| \bm{Z} - \bm{M} \|_F \bigg)^2_+ &\geq \frac{1}{2} \bigg( \frac{\|\bm{Z} - \bm{M}\|_{L^2,F}}{4 \sqrt{n}} \bigg)^2 \geq \frac{\|\bm{Z} - \bm{M}\|_{L^2,F^2}^2}{32 n}.
    \end{align}
\end{itemize}
Combining these cases, we see that we have that
\begin{align}
    \mathcal{E}(\bm{Z}) \geq \min\bigg\{ \frac{\|\bm{Z} - \bm{M}\|_{L^2,F}^2}{32n}, \frac{\lambda}{2m \sqrt{n}} \| \bm{Z} - \bm{M} \|_{L^2,F} - 2 \frac{\lambda}{n} \| \bm{M}\|_* \bigg\}.
\end{align}
In any case, when $\|\bm{Z}\|_{L^2,F} \to \infty$, since $\bm{M}$ is fixed, it holds that $\mathcal{E}(\bm{Z}) \to \infty$, whence $\mathcal{E}(\cdot)$ has minimizers.  
\\ \ \\
\noindent
\textbf{Step 2: Establishing a correspondence between soft-thresholding and minimizers}.  Suppose $\bm{Z}^*$ is any minimizer of $\mathcal{E}(\bm{Z})$.   Define the following function
 \begin{align}
     \mathcal{\widetilde E}(\bm{Z},\zeta,\tau) := \frac{\zeta}{2 n} \| \bm{Z} - \bm{M} - \tau \bm{H} \|_{L^2,F}^2 + \frac{\lambda}{n} \mathbb{E} \big\{ \| \bm{Z} \|_* - \| \bm{M} \|_* \big\}.
 \end{align}
Given $\zeta$ and $\tau$, it is clear that $\bm{Z}^*$ minimizes $\mathcal{\widetilde E}(\bm{Z},\zeta,\tau)$ if and only if $\bm{Z}$ satisfies
\begin{align}
    \bm{Z}(\bm{H}) &= {\sf S.T.} \big( \bm{M} + \tau \bm{H} ; \frac{\lambda}{\zeta} \big)
\end{align}
almost surely. Denote
\begin{align}
    \mathcal{F}(\bm{Z}) := \frac{1}{2} \bigg( \sqrt{\sigma^2  + \frac{\|\bm{Z - M}\|_F^2}{n}} - \frac{\langle \bm{H}, \bm{Z - M} \rangle_{L_2}}{n} \bigg)^2_+.
\end{align}
For fixed $\bm{Z}_1, \bm{Z}_2$, we have that
\begin{align}
    \frac{d}{d\ensuremath{\varepsilon}} \mathcal{F}\big(\bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2 \big)  &=  \bigg( \sqrt{\sigma^2 + \frac{\| \bm{Z}_1 -\ensuremath{\varepsilon} \bm{Z}_2 - \bm{M} \|_{L^2}^2}{n}} - \frac{\langle \bm{H}, \bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2 - \bm{M} \rangle }{n}\bigg)_{+} \\
    &\times \bigg( \frac{1}{2} \big( \sigma^2 + \frac{\|\bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2 - \bm{M} \|_F^2}{n} \big)^{-1/2} \bigg( \frac{2\langle \bm{Z}_1 - \bm{M}, \bm{Z}_2 \rangle + \ensuremath{\varepsilon}^2 \| \bm{Z}_2 \|^2 }{n} \bigg) -  \frac{\langle \bm{H}, \bm{Z}_2 \rangle }{n} \bigg).
\end{align}
Evaluating at $\ensuremath{\varepsilon}= 0$ yields
\begin{align}
    \frac{d}{d\ensuremath{\varepsilon}} \mathcal{F}(\bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2 ) \bigg|_{\ensuremath{\varepsilon} = 0} &=  \bigg[ \sqrt{\sigma^2 + \frac{\|\bm{Z}_1 - \bm{M} \|_{L^2}^2}{n}} - \frac{\langle \bm{H}, \bm{Z}_1 - \bm{M} \rangle }{n} \bigg]_+ \bigg[\sigma^2 + \frac{\|\bm{Z}_1 - \bm{M} \|_{L^2}^2}{n} \bigg]^{-1/2} \frac{\langle \bm{Z}_1 - \bm{M}, \bm{Z}_2 \rangle}{n} \\
    &\quad -  \bigg[\sqrt{\sigma^2 + \frac{\|\bm{Z}_1 - \bm{M} \|_{L^2}^2}{n}} - \frac{\langle \bm{H}, \bm{Z}_1 - \bm{M} \rangle }{n} \bigg]_+ \frac{\langle \bm{H}, \bm{Z}_2 \rangle}{n} \\
    &=  \mathcal{Z}(\bm{Z}_1) \frac{\langle \bm{Z}_1 - \bm{M}, \bm{Z}_2 \rangle}{n} -  \mathcal{T}(\bm{Z}_1) \mathcal{Z}(\bm{Z}_1) \frac{\langle \bm{H}, \bm{Z}_2 \rangle}{n} \\
    &=  \mathcal{Z}(\bm{Z}_1)  \frac{\langle \bm{Z}_1 - \bm{M} - \mathcal{T}(\bm{Z}_1) \bm {H} , \bm{Z}_2\rangle}{n}.
\end{align}
Therefore, it holds that
\begin{align}
    \mathcal{F}(\bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2) &= \mathcal{F}(\bm{Z}_1) + \ensuremath{\varepsilon}  \mathcal{Z}(\bm{Z}_1) \frac{\langle \bm{Z}_1 - \bm{M} - \mathcal{T}(\bm{Z}_1) \bm {H} , \bm{Z}_2\rangle}{n} + O(\ensuremath{\varepsilon}^2).
\end{align}
In addition, observe that
\begin{align}
    \mathcal{\widetilde E}(\bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2, \zeta,\tau) &= \frac{\zeta}{2n} \| \bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2 - \bm{M} - \tau \bm{H} \|_{L^2}^2 + \frac{\lambda}{n} \mathbb{E} \big\{ \|\bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2 \|_* - \bm{M}\|_* \big\} \\
    &= \frac{\zeta}{2n} \bigg( \| \bm{Z}_1 - \bm{M} - \tau \bm{H} \|^2 + 2 \ensuremath{\varepsilon} \langle \bm{Z}_1 - \bm{M} - \tau \bm{H}, \bm{Z}_2 \rangle + \ensuremath{\varepsilon}^2 \| \bm{Z}_2\|^2 \bigg) + \frac{\lambda}{n} \mathbb{E} \big\{ \| \bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2 \|_* - \| \bm{M} \|_* \big\} \\
    &= \frac{\zeta}{2n} \| \bm{Z}_1 - \bm{M} - \tau \bm{H} \|^2 +  \ensuremath{\varepsilon}  \zeta  \frac{\langle \bm{Z}_1 - \bm{M} -\tau  \bm {H} , \bm{Z}_2\rangle}{n} + O(\ensuremath{\varepsilon}^2) + \frac{\lambda}{n} \mathbb{E} \big\{ \| \bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2 \|_* - \| \bm{M} \|_* \big\}.
\end{align}
In particular, for $\zeta = \mathcal{Z}(\bm{Z}_1)$ and $\tau = \mathcal{T}(\bm{Z}_1)$ it holds that
\begin{align}
    \mathcal{\widetilde E}(\bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2, \mathcal{Z}(\bm{Z}_1), \mathcal{T}(\bm{Z}_1)) - \mathcal{E} ( \bm{Z}_1 + \ensuremath{\varepsilon} \bm{Z}_2 ) &=  \mathcal{\widetilde E}(\bm{Z}_1 , \mathcal{Z}(\bm{Z}_1), \mathcal{T}(\bm{Z}_1)) - \mathcal{E} ( \bm{Z}_1 ) + O(\ensuremath{\varepsilon}^2),
\end{align}
Consequently,  $\bm{Z}_1$ is a minimizer of $\mathcal{E}(\bm{Z}_1)$ if and only if $\bm{Z}_1$ is a minimizer of $\bm{Z}_1 \mapsto \mathcal{\widetilde E}(\bm{Z}_1, \mathcal{Z}(\bm{Z}_1), \mathcal{T}(\bm{Z}_1))$, which are simply given via
\begin{align}
    \bm{Z}^* &= {\sf S.T.} \bigg( \bm{M} + \mathcal{T}(\bm{Z}^*) \bm{H} ; \frac{\lambda}{\mathcal{Z}(\bm{Z}^*)} \bigg).
\end{align}
Since minimizers of $\mathcal{E}(\bm{Z})$ exist, it must hold that $\bm{Z}^*$ exists, and hence solutions to the fixed-point equations exist.
\\ \ \\
\noindent \textbf{Step 3: Establishing Uniqueness}.   Now suppose that $\mathcal{Z}(\bm{Z}^*) = 0$ for some minimizer $\bm{Z}^*$.  Then $\bm{Z}^* = 0$ almost surely, and hence 
\begin{align}
    \mathcal{Z}(\bm{Z}^*) =  \big( 1- \frac{\langle \bm{H}, 0 \rangle_{L_2}}{n\mathcal{T}(\bm{Z}^*)} \big)_+ = 1
\end{align}
a contradiction.  Therefore $\mathcal{Z}(\bm{Z}^*) > 0$ for all minimizers of $\mathcal{E}$.  Finally, the function $\mathcal{E}$ is strictly convex on $\mathcal{Z}(\bm{Z}) > 0$.  Because all minimizers satisfy $\mathcal{Z}(\bm{Z}) > 0$, restricting $\mathcal{E}$ to the set $\mathcal{Z}(\bm{Z}) > 0$ renders $\mathcal{E}$ strictly convex and does not eliminate any  minimizers, whence the minimizer must be unique by strict convexity.

