\begin{align}
    L_{\lambda}^{(n)}(\mathcal{W}) :=\frac{1}{dr} \bigg( \min_ {\substack{\bm{W}  \in \mathcal{W}\\ \bm{W} + \bm{M} \succcurlyeq 0}} \max_{\bm{\nu} \in \mathbb{R}^n} \| \bm{W} \|_F \langle \bm{g}, \bm{\nu} \rangle /\sqrt{n} +&\| \bm{\nu}\| \langle \bm{H}, \bm{W}
    \rangle /\sqrt{n}- \langle \bm{\ensuremath{\varepsilon}}, \bm{\nu} \rangle - \frac{1}{2} \| \bm{\nu} \|^2 \\
    &\qquad\qquad + \lambda (\| \bm{W} + \bm{M} \|_{*} - \|\bm{M}\|_* )\bigg).
\end{align}
Again, the argument of $L_{\lambda}^{(n)}$ is a set (the set for which $\bm{W}$ is minimized over). 
Therefore, it suffices to analyze the minimum value of $L_{\lambda}^{(n)}$ over $\mathbb{R}^{d\times d}$.  By expanding $L_{\lambda}^{(n)}$ out further and manipulating, we can show that 
\begin{subequations}
\label{l_lambda_n1}    
\begin{align}
    L_{\lambda}^{(n)}(\mathbb{R}^{d\times d}) &= \max_{\beta > 0} \min_{\tau \geq \sigma} \bigg( \frac{\sigma^2}{\tau} + \tau \bigg) \frac{\|\bm{g}\|}{\sqrt{n}}\frac{\gamma_n \beta}{2} - \gamma_n \frac{\beta^2}{2} \\
    &\quad + \min_{ \substack{\bm{W} \in\mathbb{R}^{d\times d}\\\bm{W} + \bm{M} \succcurlyeq 0}} \bigg\{  \beta \frac{\|\bm{W}\|_F^2}{2 dr \tau} + \beta \frac{\langle \bm{H}, \bm{W} \rangle}{dr} + \frac{\lambda}{dr} \big\{ \| \bm{W} + \bm{M} \|_* - \|\bm{M} \|_* \big\} \bigg\}.
\end{align}
\end{subequations}
After changing variables back to $\bm{Z} = \bm{W} + \bm{M}$, the inner minimization can be obtained by soft-thresholding $\bm{M} + \tau \bm{H}$ at level $\lambda/\zeta$ where $\zeta = \tau\beta$.

We prove the result first for hard thresholding.
 First, define the event
    \begin{align}
        \mathcal{E} 
        &:= \bigg\{ \| \bm{H} \| \leq C \sqrt{d} \bigg\}.
    \end{align}
 We observe that on $\mathcal{E}$, since $\lambda \geq C_3 \sigma \sqrt{d}$ and $\tau^* \leq C \sigma$ by \cref{lem:fxdpointprops}, it holds that $\bm{Z}_{{\sf HT}}^{(\lambda)}$ is rank $r$. Consequently, on this event,
\begin{align}
    \phi\bigg( \bm{Z}_{{\sf HT}}^{(\lambda)} \bigg) &= \phi\bigg( \mathcal{P}_{{\sf rank}-r}(\bm{M} + \tau^* \bm{H} ) \bigg) \\
    &= \phi\bigg( \mathcal{P}_{{\sf rank}-r}\bigg[\bm{M} + \sigma \bigg( 1 + O\big( \frac{dr}{n} \big)\bigg) \bm{H} \bigg] \bigg).
\end{align}
Let $\bm{U}_{\sigma} \bm{\Lambda}_{\sigma} \bm{U}_{\sigma}^{\top}$ denote the leading rank $r$ approximation of $\bm{M} + \sigma \bm{H}$, and let $\bm{U}_{\tau} \bm{\Lambda}_{\tau} \bm{U}_{\tau}^{\top}$ be the leading rank $r$ approximation of $\bm{M} + \tau^* \bm{H}$.  Recall that we let $\mathcal{O}_{\bm{U}_{\sigma},\bm{U}_{\tau}}$ denote the Frobenius-optimal orthogonal matrix aligning $\bm{U}_{\sigma}$ to $\bm{U}_{\tau}$.  We have
\begin{align*}
    \| \bm{Z}_{{\sf HT}}^{(\lambda)} - \bm{Z}_{{\sf HT}} \|_F &= \| \bm{U}_{\sigma} \bm{\Lambda}_{\sigma} \bm{U}_{\sigma}^{\top} - \bm{U}_{\tau} \bm{\Lambda}_{\tau} \bm{U}_{\tau}^{\top} \|_F \\
    &\leq \| \bm{U}_{\sigma} \bm{\Lambda}_{\sigma} \big(  \bm{U}_{\sigma} - \bm{U}_{\tau} \mathcal{O}_{\bm{U}_{\tau}, \bm{U}_{\sigma}} \big)^{\top}  \|_F +  \| \bm{U}_{\sigma} \big[ \bm{\Lambda}_{\sigma} \mathcal{O}_{\bm{U}_{\tau},\bm{U}_{\sigma}}^{\top} -  \mathcal{O}_{\bm{U}_{\tau},\bm{U}_{\sigma}}^{\top}  \bm{\Lambda}_{\tau} \big] \bm{U}_{\tau}^{\top} \|_F \\
    &\quad + \| \big[ \bm{U}_{\sigma} \mathcal{O}_{\bm{U}_{\tau},\bm{U}_{\sigma}}^{\top} - \bm{U}_{\tau} \big] \bm{\Lambda}_{\tau} \bm{U}_{\tau}^{\top} \|_F \\
    &\leq \underbrace{\| \bm{U}_{\sigma} \bm{\Lambda}_{\sigma} \big(  \bm{U}_{\sigma} - \bm{U}_{\tau} \mathcal{O}_{\bm{U}_{\tau}, \bm{U}_{\sigma}} \big)^{\top}  \|_F + \| \big[ \bm{U}_{\sigma} \mathcal{O}_{\bm{U}_{\tau},\bm{U}_{\sigma}}^{\top} - \bm{U}_{\tau} \big] \bm{\Lambda}_{\tau} \bm{U}_{\tau}^{\top} \|_F}_{=: T_1} \\
    &\quad + \underbrace{\| \bm{\Lambda}_{\sigma}\big[ \mathcal{O}_{\bm{U}_{\tau},\bm{U}_{\sigma}}^{\top} - \bm{U}_{\sigma}^{\top} \bm{U}_{\tau} \big] \|_F  + \| \big[ \bm{U}_{\sigma}^{\top} \bm{U}_{\tau} - \mathcal{O}_{\bm{U}_{\sigma},\bm{U}_{\tau}} \big] \bm{\Lambda}_{\tau} \|_F}_{=:T_2} + \underbrace{\| \bm{\Lambda}_{\sigma}\bm{U}_{\sigma}^{\top} \bm{U}_{\tau} - \bm{U}_{\sigma}^{\top} \bm{U}_{\tau} \bm{\Lambda}_{\tau} \|_F}_{=:T_3}.
\end{align*}
We will analyze each term in turn.  First, we note that on the event $\mathcal{E}$ it holds that 
\begin{align*}
    \max\big\{ | \lambda_{r}(\bm{M} + \sigma \bm{H}) - \lambda_{r+1}(\bm{M} + \tau^* \bm{H})|, | \lambda_{r+1}(\bm{M} + \sigma \bm{H}) - \lambda_{r}(\bm{M} + \tau^* \bm{H})| \big\} \leq C \sigma \sqrt{d} \leq \lambda_{\min}(\bm{M}).
\end{align*}
Consequently, the Davis-Kahan Theorem implies
\begin{align*}
    \| \bm{U}_{\sigma} \mathcal{O}_{\bm{U}_{\sigma} \bm{U}_{\tau}} - \bm{U}_{\tau} \|_F \leq \sqrt{r}  \| \bm{U}_{\sigma} \mathcal{O}_{\bm{U}_{\sigma} \bm{U}_{\tau}} - \bm{U}_{\tau} \| \leq C \frac{|\tau^* - \sigma| \sqrt{dr}}{\lambda_r(\bm{M})}.
\end{align*}
We also note that
\begin{align*}
    \| \mathcal{O}_{\bm{U}_{\sigma} \bm{U}_{\tau}} - \bm{U}_{\sigma}^{\top} \bm{U}_{\tau} \| \leq 1 - \| \cos\Theta(\bm{U}_{\sigma},\bm{U}_{\tau}) \|  \leq \| \sin\Theta(\bm{U}_{\sigma},\bm{U}_{\tau}) \|^2 \leq C^2 \frac{|\tau^* - \sigma |^2 dr}{\lambda_r^2(\bm{M})},
\end{align*}
which follows from the fact that $\mathcal{O}_{\bm{U}_{\sigma},\bm{U}_{\tau}}$ is computed from the SVD of $\bm{U}_{\sigma}^{\top} \bm{U}_{\tau}$, and the singular values of $\bm{U}_{\sigma}^{\top} \bm{U}_{\tau}$ are equal to the cosines of the principal angles between the subspaces.  We now anlyze each term.
\begin{itemize}
    \item \textbf{The term $T_1$.}  We have that 
    \begin{align*}
         \| \big[ \bm{U}_{\sigma} \mathcal{O}_{\bm{U}_{\tau},\bm{U}_{\sigma}}^{\top} - \bm{U}_{\tau} \big] \bm{\Lambda}_{\tau} \bm{U}_{\tau}^{\top} \|_F \leq \| \bm{\Lambda}_{\tau} \| \frac{C |\tau^* - \sigma| \sqrt{dr}}{\lambda_r(\bm{M})} \lesssim | \tau^* - \sigma | \sqrt{dr}.
    \end{align*}
    The same bound holds for the other term.  
    \item \textbf{The term $T_2$.} We have 
    \begin{align}
   \| \bm{\Lambda}_{\sigma}\big[ \mathcal{O}_{\bm{U}_{\tau},\bm{U}_{\sigma}}^{\top} - \bm{U}_{\sigma}^{\top} \bm{U}_{\tau} \big] \|_F &\leq \| \bm{\Lambda}_{\sigma} \| C^2 \frac{|\tau^* - \sigma |^2 dr}{\lambda_r^2(\bm{M})} \leq C'  |\tau^* - \sigma |^2 \sqrt{dr} \frac{\sqrt{dr}}{\lambda_{r}(\bm{M})},
    \end{align}
    which follows by \cref{ass1}.  A similar bound holds for the other quantity.
    \item \textbf{The term $T_3$.} We observe that  
    \begin{align*}
        \| \bm{\Lambda}_{\sigma} \bm{U}_{\sigma}^{\top} \bm{U}_{\tau} - \bm{U}_{\sigma}^{\top} \bm{U}_{\tau} \bm{\Lambda}_{\tau} \|_F &= \| \bm{U}_{\sigma}^{\top} \big[ \bm{M} + \tau^* \bm{H} - ( \bm{M} + \sigma \bm{H}) \big] \bm{U}_{\tau} \|_F \\
        &\lesssim \sqrt{rd} | \tau^* - \sigma|.
    \end{align*}
\end{itemize}
Combining these results, we have that on the event $\mathcal{E}$,
\begin{align*}
    \| \bm{Z}_{{\sf HT}}^{(\lambda)} - \bm{Z}_{{\sf HT}} \|_F \leq C | \tau^* - \sigma | \sqrt{dr} + C \sqrt{dr} | \tau^* - \sigma |^2.
\end{align*}
By \cref{lem:fxdpointprops} it holds that 
\begin{align*}
    |\tau^* - \sigma| \leq \frac{|(\tau^*)^2 - \sigma^2|}{\tau^* + \sigma} &= O\bigg( \frac{dr}{n} \sigma \bigg).
\end{align*}
Therefore, we have that  on the event $\mathcal{E}$,
\begin{align*}
    \| \bm{Z}_{{\sf HT}}^{(\lambda)} - \bm{Z}_{{\sf HT}} \|_F &= O \bigg( \frac{dr}{n} \sigma \bigg).
\end{align*}
Consequently,
 \begin{align}
 \bigg|        \mathbb{E}\bigg\{ \phi\bigg( \frac{\bm{Z}_{{\sf HT}}^{(\lambda)}}{\sqrt{dr}} \bigg) - \phi \bigg( \frac{\bm{Z}_{{\sf HT}}}{\sqrt{dr}} \bigg) \bigg\} \bigg| &\leq \frac{1}{\sqrt{dr}}\mathbb{E} \| \bm{Z}_{{\sf HT}}^{(\lambda)} - \bm{Z}_{{\sf HT}} \|_F \\
 &\leq O\bigg( \frac{dr}{n} \sigma \bigg) + \frac{1}{\sqrt{dr}} \bigg( \mathbb{E}  \| \bm{M} + \tau^* \bm{H} \|_F \mathbb{I}_{\mathcal{E}^c}  + \mathbb{E}  \| \bm{M} + \sigma^* \bm{H} \|_F \mathbb{I}_{\mathcal{E}^c} \bigg)\\ 
 &\leq O \bigg( \frac{dr}{n} \sigma \bigg) + \frac{\| \bm{M} \|}{\sqrt{dr}} \mathbb{P}\{ \mathcal{E}^c \} +  \frac{1}{\sqrt{r}} \mathbb{E} \| \bm{H} \| \mathbb{I}_{\mathcal{E}^c} \\
 &\leq O\bigg( \frac{dr}{n} \sigma \bigg) + C \exp( - c d) + \frac{1}{\sqrt{r}} \int_{C\sqrt{d}}^{\infty} \exp( - c s^2) ds \\
 &= O\bigg( \frac{dr}{n} \sigma \bigg).
 \end{align}
 Here we have used the fact that $\mathbb{P}\{ \|\bm{H}\| \geq C \sqrt{d} + s \} \leq 2 \exp( - c s^2)$ by standard tail bounds for norms of random matrices \citep{bandeira_sharp_2016}.  


We now prove the result for soft thresholding.  First, we note that the exact same argument continues applies if we
make the replacement $\bm{M} \mapsto \bm{M} - \lambda \bm{I}$.  Consequently, we have that 
\begin{align}
\bigg|     \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)}{\sqrt{dr}} \bigg) - \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda)}(\sigma)}{\sqrt{dr}} \bigg) \bigg| &\leq \bigg|     \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda)}(\tau^*)}{\sqrt{dr}} \bigg) - \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda)}(\sigma)}{\sqrt{dr}} \bigg) \bigg| \\
&\quad + \bigg|     \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)}{\sqrt{dr}} \bigg) - \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda)}(\tau^*)}{\sqrt{dr}} \bigg) \bigg| \\
&\leq O\bigg( \frac{dr}{n} \sigma \bigg) + \bigg|     \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)}{\sqrt{dr}} \bigg) - \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda)}(\tau^*)}{\sqrt{dr}} \bigg) \bigg|.
\end{align}
Therefore, it suffices to focus on the second term.  

On the event $\mathcal{E}$ the quantity $\bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)$ is simply hard thresholding of $\bm{M} -\lambda + \tau^* \bm{H}$ at level $\lambda/\zeta^*$, and similarly for  $\bm{Z}_{{\sf ST}}^{(\lambda)}(\tau^*)$.  Therefore, both matrices share the same eigenvectors, and hence on the event $\mathcal{E}$,
\begin{align*}
    \|\bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*) - \bm{Z}_{{\sf ST}}^{(\lambda)}(\tau^*) \|_F \leq \sqrt{2r} \lambda \bigg( \frac{1}{\zeta^*} - 1 \bigg) = O\bigg( \sigma \sqrt{rd} \times \frac{d r^{3/2}}{n} \bigg),
\end{align*}
where we have used the fact that $|\zeta^*  - 1 | = O\bigg( \frac{d r^{3/2}}{n} \bigg)$ by \cref{lem:fxdpointprops}.  Therefore, the same argument as for $\bm{Z}_{{\sf HT}}$ shows that 
\begin{align}
\bigg|     \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)}{\sqrt{dr}} \bigg) - \mathbb{E} \phi\bigg( \frac{\bm{Z}_{{\sf ST}}^{(\lambda)}(\sigma)}{\sqrt{dr}} \bigg) \bigg| &= O\bigg( \frac{d r^{3/2}}{n} \bigg).
\end{align}

