    Let $\Delta = \bm{U} - \bm{U}_2\mathcal{O}_{\bm{U},\bm{U}_2}$.  Then it holds that
    \begin{align}
     \nabla^2 f^{(\lambda)}_{{\sf ncvx}}(\bm{U}) [ \bm{\Delta},\bm{\Delta}] &= .5 \langle \mathcal{X}(\bm{\Delta \Delta}^{\top}), \mathcal{X}(\bm{\Delta \Delta}^{\top}) \rangle \\
    &\qquad + 4  \langle \nabla f^{(\lambda)}_{{\sf ncvx}}(\bm{U}),\Delta \rangle + \frac{4}{\sqrt{n}} \sum_{i=1}^{n} \ensuremath{\varepsilon}_i\langle \bm{X}_i, \bm{U\Delta}^{\top} \rangle - 4 \lambda \langle \bm{U},\bm{\Delta} \rangle \\
   &\qquad - 1.5 \langle \mathcal{X}(\bm{UU}^{\top} - \bm{M}) ,\mathcal{X}(\bm{UU}^{\top} - \bm{M}) \rangle \\
    &\qquad + \frac{1}{\sqrt{n}} \sum_{i=1}^{n} \big[ \ensuremath{\varepsilon}_i \langle \bm{X}_i, \bm{\Delta},\bm{\Delta \rangle}] +  \lambda \| \bm{\Delta}\|_F^2.
\end{align}

First we will show that $\nabla^2 f^{(\lambda)}_{{\sf ncvx}}(\bm{U})[ \bm{\Delta}, \bm{\Delta}]$ is upper bounded when $\bm{U}$ is a critical point of $f^{(\lambda)}_{{\sf ncvx}}$.  The proof is motivated by \citet{ge_no_2017}.

First, on the event $\mathcal{E}_{{\sf Good}}$, we have that
\begin{align}
\bigg|    \frac{4}{\sqrt{n}} \sum_{i=1}^{n} \ensuremath{\varepsilon}_i \langle \bm{X}_i, \bm{U\Delta}^{\top} \rangle \bigg| &\leq C \sigma \sqrt{dr} \| \bm{U\Delta}^{\top} \|_F; \\
\bigg| \frac{1}{\sqrt{n}} \sum_{i=1}^{n} \ensuremath{\varepsilon}_i \langle \bm{X}_i, \bm{\Delta \Delta}^{\top} \rangle \bigg| &\leq C \sigma \sqrt{dr} \| \bm{\Delta\Delta}^{\top} \|_F
\end{align}
By the restricted isometry property (e.g. Lemma 3 of \citet{chi_nonconvex_2019}), we have that
\begin{align}
    \bigg| \big\langle \mathcal{X}(\bm{UU}^{\top} - \bm{M}), \mathcal{X}(\bm{UU}^{\top} - \bm{M}) \big \rangle - \langle \bm{UU}^{\top} - \bm{M},  \bm{UU}^{\top} - \bm{M}\rangle \bigg| \leq \delta_{2r} \| \bm{UU}^{\top} - \bm{M} \|_F^2
\end{align}
and
\begin{align}
    \bigg| \langle \mathcal{X}( \bm{\Delta \Delta}^{\top}  ) ,  \mathcal{X}( \bm{\Delta \Delta}^{\top}) \rangle - \langle \bm{\Delta \Delta}^{\top}, \bm{\Delta \Delta}^{\top} \rangle \bigg| \leq \delta_{2r}  \| \bm{\Delta \Delta}^{\top} \|_F^2
\end{align}
Consequently, if $\bm{U}$ satisfies $\nabla f^{(\lambda)}_{{\sf ncvx}}(\bm{U}) = 0$, 
    \begin{align}
     \nabla^2 f^{(\lambda)}_{{\sf ncvx}}(\bm{U})[ \bm{\Delta},\bm{\Delta}] & \leq .5\big( 1 + \delta_{2r}) \| \bm{\Delta \Delta}^{\top} \|_F^2 \\
     &\qquad + C \sigma \sqrt{dr} \big( \| \bm{U\Delta}^{\top} \|_F + \| \bm{\Delta\Delta}^{\top} \|_F \big) \\
     &\quad - 1.5( 1 - \delta_{2r}) \| \bm{UU}^{\top} - \bm{M} \|_F^2 \\
     &\qquad + \lambda \| \bm{\Delta}\|_F^2 - 4 \lambda \langle \bm{U,\Delta} \rangle.
     \end{align}
     Next, we note that by Lemma 6 of \citet{ge_no_2017}, if $\bm{\Delta} = \bm{U}^* - \bm{U}\mathcal{O}_{\bm{U},\bm{U}^*}$  and $\bm{U}^* \bm{U}^{*\top} = \bm{M}$, then 
     \begin{align}
         \| \bm{\Delta\Delta}^{\top} \|_F^2 \leq 2 \| \bm{UU}^{\top} - \bm{M} \|_F^2; \qquad \| \bm{\Delta}\|_F^2 \leq \frac{1}{2(\sqrt{2} - 1) \lambda_r(\bm{M})} \| \bm{UU}^{\top} - \bm{M} \|_F^2.
     \end{align}
