    \begin{align}
     \nabla^2 f^{(\lambda)}_{{\sf ncvx}}(\bm{U})[ \bm{\Delta},\bm{\Delta}] & \leq \big( 1 + \delta_{2r}) \| \bm{UU}^{\top} - \bm{M} \|_F^2 \\
     &\qquad + C \sigma \sqrt{dr} \big( \| \bm{U\Delta}^{\top} \|_F + \| \bm{UU}^{\top} - \bm{M} \|_F \big) \\
     &\quad - 1.5( 1 + \delta_{2r}) \| \bm{UU}^{\top} - \bm{M} \|_F^2 \\
     &\qquad + \lambda \frac{1}{2(\sqrt{2} - 1) \lambda_r(\bm{M})} \| \bm{UU}^{\top} - \bm{M} \|_F^2 - 4 \lambda \langle \bm{U,\Delta} \rangle \\
     &= \| \bm{UU}^{\top} - \bm{M} \|_F^2 \bigg( - .5 + .5 \delta_{2r} + \frac{\lambda}{2 (\sqrt{2} - 1) \lambda_r(\bm{M})} \bigg)  \\
     &\qquad + C \sigma \sqrt{dr} \bigg( \| \bm{U}\bm{\Delta}^{\top} \|_F + \| \bm{UU}^{\top} - \bm{M} \|_F\bigg) \\
     &\qquad - 4 \lambda \langle \bm{U,\Delta} \rangle.
     \end{align}
     We further have that
     \begin{align}
         \| \bm{U\Delta}^{\top} \|_F &\leq \| ( \bm{U} - \bm{U}^* (\mathcal{O}_{\bm{U},\bm{U}^*})^{\top}) \bm{\Delta}^{\top} \|_F + \| \bm{U}^* \| \| \bm{\Delta} \|_F \\
         &\leq \| \bm{\Delta\Delta}^{\top} \|_F +  \| \bm{U}^* \| \| \bm{\Delta} \|_F \\
         &\leq \sqrt{2} \| \bm{UU}^{\top} - \bm{M} \|_F + \sqrt{\frac{\lambda_1(\bm{M})}{\lambda_r(\bm{M})}} \frac{1}{\sqrt{2(\sqrt{2}-1)}} \| \bm{UU}^{\top} - \bm{M} \|_F \\
         &\leq (\sqrt{\kappa} + \sqrt{2}) \| \bm{UU}^{\top} - \bm{M} \|_F,
     \end{align}
     where the same bound holds for $\langle \bm{U},\bm{\Delta} \rangle$.  Consequently, plugging this in, we obtain
    \begin{align}
     \nabla^2 f^{(\lambda)}_{{\sf ncvx}}(\bm{U})[ \bm{\Delta},\bm{\Delta}] & \leq \big( 1 + \delta_{2r}) \| \bm{UU}^{\top} - \bm{M} \|_F^2 \\
     &\qquad + C \sigma \sqrt{dr} \big( \| \bm{U\Delta}^{\top} \|_F + \| \bm{UU}^{\top} - \bm{M} \|_F \big) \\
     &\quad - 1.5( 1 + \delta_{2r}) \| \bm{UU}^{\top} - \bm{M} \|_F^2 \\
     &\qquad + \lambda \frac{1}{2(\sqrt{2} - 1) \lambda_r(\bm{M})} \| \bm{UU}^{\top} - \bm{M} \|_F^2 - 4 \lambda \langle \bm{U,\Delta} \rangle \\
     &= \| \bm{UU}^{\top} - \bm{M} \|_F^2 \bigg( - .5 + .5 \delta_{2r} + \frac{\lambda}{2 (\sqrt{2} - 1) \lambda_r(\bm{M})} \bigg)  \\
     &\qquad + C \sigma \sqrt{dr} \bigg( (\sqrt{\kappa} + \sqrt{2}) \| \bm{UU}^{\top} - \bm{M} \|_F + \| \bm{UU}^{\top} - \bm{M} \|_F\bigg) \\
     &\qquad +  4 \lambda(\sqrt{\kappa} + \sqrt{2}) \| \bm{UU}^{\top} - \bm{M} \|_F \\
     &= \| \bm{UU}^{\top} - \bm{M} \|_F^2 \bigg( - .5 + .5 \delta_{2r} + \frac{\lambda}{2 (\sqrt{2} - 1) \lambda_r(\bm{M})} \bigg) \\
     &\qquad + \| \bm{UU}^{\top} - \bm{M} \|_F \bigg( C \sigma  \sqrt{\kappa dr} +  4 \lambda \sqrt{\kappa} \bigg).
     \end{align}
 Under the assumption that $\delta_{2r} \leq \frac{1}{10}$, $\lambda_r(\bm{M}) \geq C_1 \sigma \sqrt{dr}$, and $C_3 \sigma \sqrt{d} \leq \lambda \leq C_4 \sigma \sqrt{d}$, it holds that
