First, we have that 
\begin{align}
    f^{(\lambda)}_{{\sf ncvx}}(\bm{U}) &= \frac{1}{4} \sum_{i=1}^{n} \bigg[ y_i - \langle \bm{UU}^{\top}, \bm{X}_i \rangle/\sqrt{n} \bigg]^2 + \frac{\lambda}{2} \| \bm{U} \|_F^2,
\end{align}
whence
\begin{align}
    \nabla f^{(\lambda)}_{{\sf ncvx}}(\bm{U}) &= \sum_{i=1}^{n} \bigg[ \langle \bm{UU}^{\top} , \bm{X}_i \rangle/\sqrt{n} - y_i \bigg] \bm{X}_i\bm{U} + \lambda \bm{U}.
\end{align}
As a result,
\begin{align}
    \nabla^2 &f^{(\lambda)}_{{\sf ncvx}}(\bm{U})[ \bm{\Delta},\bm{\Delta}] \\
    &= \frac{d}{dt} \langle \nabla f^{(\lambda)}_{{\sf ncvx}}(\bm{U} + t \bm{\Delta}) , \bm{\Delta} \rangle\bigg|_{t=0} \\
    &= \frac{d}{dt} \bigg\langle \sum_{i=1}^{n} \bigg[ \langle \bm{(U + t \bm{\Delta})(U + t \Delta)}^{\top} , \bm{X}_i \rangle/\sqrt{n} - y_i \bigg] \bm{X}_i (\bm{U} + t \bm{\Delta}) + \lambda (\bm{U} + t \bm{\Delta}) , \bm{\Delta} \bigg\rangle\bigg|_{t=0} \\
    &=   \frac{1}{n}\sum_{i=1}^{n} \bigg \langle \bm{\Delta U}^{\top} + \bm{U\Delta}^{\top}, \bm{X}_i \bigg \rangle \bigg\langle \bm{X}_i \bm{U}, \bm{\Delta} \bigg \rangle + \frac{1}{\sqrt{n}} \sum_{i=1}^{n} \bigg[  \langle \bm{UU}^{\top} , \bm{X}_i \rangle/\sqrt{n} - y_i \bigg] \langle \bm{X}_i \bm{\Delta},\bm{\Delta} \rangle +  \lambda \| \bm{\Delta} \|_F^2
    \\
    &=  \frac{1}{n} 2 \sum_{i=1}^{n} \bigg \langle  \bm{U\Delta}^{\top}, \bm{X}_i \bigg \rangle \bigg\langle \bm{X}_i \bm{U}, \bm{\Delta} \bigg \rangle + \frac{1}{\sqrt{n}} \sum_{i=1}^{n} \bigg[  \langle \bm{UU}^{\top} , \bm{X}_i \rangle/\sqrt{n} - y_i \bigg] \langle \bm{X}_i \bm{\Delta},\bm{\Delta} \rangle + \lambda \| \bm{\Delta} \|_F^2  \\
    &= \frac{1}{n} 2 \sum_{i=1}^{n} \bigg \langle  \bm{U\Delta}^{\top}, \bm{X}_i \bigg \rangle^2  + \frac{1}{n} \sum_{i=1}^{n} \bigg[  \langle \bm{UU}^{\top} - \bm{M} , \bm{X}_i \rangle \bigg] \langle \bm{X}_i \bm{\Delta},\bm{\Delta} \rangle - \frac{1}{\sqrt{n}}\sum_{i=1}^{n} \bigg[ \ensuremath{\varepsilon}_i \langle \bm{X}_i \bm{\Delta}, \bm{\Delta} \rangle \bigg] +\lambda \| \bm{\Delta} \|_F^2 \\
    &= .5 \big \langle \mathcal{X}( \bm{U\Delta}^{\top} + \bm{\Delta U}^{\top}),\mathcal{X}( \bm{U\Delta}^{\top} + \bm{\Delta U}^{\top}) \big \rangle \\
    &\qquad +  \langle \mathcal{X}( \bm{UU}^{\top} -  \bm{M}   ) ,  \mathcal{X}( \bm{\Delta \Delta}^{\top}) \rangle  + \frac{1}{\sqrt{n}}\sum_{i=1}^{n} \bigg[ \ensuremath{\varepsilon}_i \langle \bm{X}_i \bm{\Delta}, \bm{\Delta} \rangle \bigg] +\lambda \| \bm{\Delta} \|_F^2.
\end{align}
Next, we note that
\begin{align}
    \bm{UU}^{\top} - \bm{M} + \bm{\Delta \Delta}^{\top} = \bm{U\Delta}^{\top} + \bm{\Delta U}^{\top}.
\end{align}
Plugging this in yields
\begin{align}
   \nabla^2 f^{(\lambda)}_{{\sf ncvx}}(\bm{U})[ \bm{\Delta},\bm{\Delta}] 
    &= .5 \langle \mathcal{X}( \bm{\Delta\Delta}^{\top} ),\mathcal{X}( \bm{\Delta\Delta}^{\top} ) \rangle \\
    &\qquad + 2\langle \mathcal{X}(\bm{UU}^{\top} - \bm{M}), \mathcal{X}(\bm{U\Delta}^{\top} + \bm{\Delta U}^{\top}) \rangle  \\
    &\qquad - 1.5 \langle \mathcal{X}(\bm{UU}^{\top} - \bm{M}) ,\mathcal{X}(\bm{UU}^{\top} - \bm{M}) \rangle \\
    &\qquad + \frac{1}{\sqrt{n}} \sum_{i=1}^{n} \big[ \ensuremath{\varepsilon}_i \langle \bm{X}_i, \bm{\Delta},\bm{\Delta \rangle}] +  \lambda \| \bm{\Delta}\|_F^2.
\end{align}
In addition, we have that
\begin{align}
  \langle \nabla f^{(\lambda)}_{{\sf ncvx}}(\bm{U}), \Delta \rangle &= .5 \langle \mathcal{X}( \bm{UU}^{\top} - \bm{M}), \mathcal{X}(\bm{U} \Delta^{\top} + \bm{\Delta U}^{\top} ) \rangle - \frac{1}{\sqrt{n}} \sum_{i=1}^{n} \ensuremath{\varepsilon}_i \langle \bm{X}_i, \bm{U \Delta}^{\top}\rangle + \lambda \langle \bm{U}, \bm{\Delta} \rangle,
\end{align}
whence
\begin{align}
     \nabla^2 f^{(\lambda)}_{{\sf ncvx}}(\bm{U}) [ \bm{\Delta},\bm{\Delta}] &= .5 \langle \mathcal{X}(\bm{\Delta \Delta}^{\top}), \mathcal{X}(\bm{\Delta \Delta}^{\top}) \rangle \\
    &\qquad + 4  \langle \nabla f^{(\lambda)}_{{\sf ncvx}}(\bm{U}),\Delta \rangle + \frac{4}{\sqrt{n}} \sum_{i=1}^{n} \ensuremath{\varepsilon}_i\langle \bm{X}_i, \bm{U\Delta}^{\top} \rangle - 4 \lambda \langle \bm{U},\bm{\Delta} \rangle \\
   &\qquad - 1.5 \langle \mathcal{X}(\bm{UU}^{\top} - \bm{M}) ,\mathcal{X}(\bm{UU}^{\top} - \bm{M}) \rangle \\
    &\qquad + \frac{1}{\sqrt{n}} \sum_{i=1}^{n} \big[ \ensuremath{\varepsilon}_i \langle \bm{X}_i, \bm{\Delta},\bm{\Delta \rangle}] +  \lambda \| \bm{\Delta}\|_F^2.
\end{align}
This completes the proof.

