    &\subset \bigg\{ \exists \bm{W} : \bm{W} + \bm{M} \succcurlyeq 0, \mathrm{rank}(\bm{W} + \bm{M}) \leq r, \bm{W} \notin \mathcal{D}_{\ensuremath{\varepsilon}/2},\|\bm{W}\|_F \leq C \sigma \sqrt{dr}, \\
    &\quad \quad \quad C^{(n)} (\bm{W}) \leq \min_{\bm{W}:\|\bm{W}\|_F \leq C \sigma \sqrt{dr}} C^{(n)}(\bm{W}) \bigg\} \\
    &\subset \bigg\{ \exists \bm{W} : \bm{W} + \bm{M} \succcurlyeq 0, \mathrm{rank}(\bm{W} + \bm{M}) \leq r, \bm{W} \in \mathcal{D}^{c}_{\ensuremath{\varepsilon}/2}, \|\bm{W}\|_F \leq C \sigma \sqrt{dr}, \\
