\label{lem:concentrationlemmapart1}
Suppose \cref{ass1,ass2,ass3} are satisfied.  Let $R = C \sigma \sqrt{dr}$, with $C$ as in \cref{lem:uncvxgood}. 
Then with probability at least 
$1 -   \frac{1}{\ensuremath{\varepsilon}} \exp( - c n \ensuremath{\varepsilon}^2) - \exp(-dr \ensuremath{\varepsilon}^2) $
it holds that
\begin{align}
    L_{\lambda}^{(n)}\bigg( \| \bm{W} \|_F \leq R; \bm{W} + \bm{M} \succcurlyeq 0 \bigg) \geq L_{\lambda}^* - C \sqrt{\gamma_n} \ensuremath{\varepsilon}.
\end{align}

\label{lem:hstronglyconvex} Suppose \cref{ass1,ass2,ass3} are satisfied.
   Let $h(\bm{U})$ be defined in $\eqref{hdef}$.  Let $\bm{M} = \bm{U}^* \bm{U}^{*\top}$ with $\bm{U}^* \in \mathbb{R}^{d \times r}$.  Define the event
