 \label{lem:miolaneb1analogue}
Let $h: \mathbb{R}^{d \times r} \to \mathbb{R}$ be a function such that $h(\bm{U} \mathcal{O}) = h(\bm{U})$ for all orthogonal matrices $\mathcal{O}$. 
Let $\mathbb{B}(\bm{\widehat U},K)$ denote the set of matrices $\bm{U}$ such that $\|\bm{U} \mathcal{O}_{\bm{U},\bm{\widehat U}} - \bm{\widehat U} \|_F \leq K$. 
Suppose that for all $\bm{U} \in \mathbb{B}(\bm{\widehat U},r)$ it holds that
    \begin{align}
        \nabla^2 h(\bm{U})[ \bm{V},\bm{V}] \geq \gamma \| \bm{V} \|_F^2,
    \end{align}
    where $\bm{V} = \bm{U}_1 - \bm{U} \mathcal{O}_{\bm{U},\bm{U}_1}$.  Suppose further that
    \begin{align}
        h(\bm{\widehat U}) \leq \min_{\mathbb{B}(\bm{\widehat U},K)} h(\bm{U}) + \ensuremath{\varepsilon}.
    \end{align}
    Then if $\bm{U}_0$ is any minimizer of $h$ over this set, it  holds that
    \begin{align}
        \| \bm{\widehat U} - \bm{U}_0 \mathcal{O}_{\bm{U}_0, \bm{\widehat U}} \|_F^2 \leq \frac{2}{\gamma} \ensuremath{\varepsilon}.  
    \end{align}
    Furthermore, it must be that for all $\bm{\widetilde U} \in \mathbb{B}(\bm{\widehat U},K)$, $h(\bm{\widetilde U}) \leq \min_{\mathbb{B}(\bm{\widehat U},K)} h(\bm{U}) + \ensuremath{\varepsilon}$ and $\| \bm{\widetilde U} \mathcal{O}_{\bm{\widetilde U},\bm{\widehat U}} - \bm{\widehat U} \|_F^2 \leq \frac{8}{\gamma} \ensuremath{\varepsilon} $.

Recall that we aim to show that:
\begin{align}
    L_{\lambda}^{(n)} \bigg( \| \bm{W} \|_F \leq R \cap PSD \bigg) \leq L_{\lambda}^* + C \ensuremath{\varepsilon}^2; \\
    L_{\lambda}^{(n)} \bigg( \mathbb{B}_{\ensuremath{\varepsilon}/2} \bigg( \bm{\widehat W}/\sqrt{dr} \bigg)^c \cap \mathrm{rank}(\bm{W+ M} ) \leq r \cap\|\bm{W} \|_F \leq R \bigg) > L_{\lambda}^* + C \ensuremath{\varepsilon}^2
    \end{align}
    with high probability. 
    We split up the proof into steps.
\\
 \ \\ \noindent \textbf{Step 1: Good events.} First, let $\mathcal{E}_{\text{\cref{lem:Zstgoodproperties}}}$ denote the event from \cref{lem:Zstgoodproperties}. On this event, it holds that $\mathrm{rank}(\bm{ Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)) \leq r$, whence the quantity $\bm{\widehat U}$ is well-defined on this event.  When $\bm{\widehat U}$ is well-defined,  define the event
\begin{align}
\mathcal{E}_1 : =     \bigg\{ h(\bm{\widehat U}) \leq L_{\lambda}^* + C \sqrt{\gamma_n} \widetilde \ensuremath{\varepsilon} \bigg\},
\end{align}
where $\widetilde \ensuremath{\varepsilon}$ will be chosen momentarily.  We also define the event 
\begin{align}
\mathcal{E}_2 :=  \bigg\{    L_{\lambda}^{(n)}\big( \| \bm{W} \|_F \leq R \cap \bm{W} + \bm{M} \succcurlyeq 0 \cap \mathrm{Rank}(\bm{W} + \bm{M}) \leq r \big) \geq L_{\lambda}^* - C \widetilde \ensuremath{\varepsilon} \sqrt{\gamma_n} \bigg\},
\end{align}
where $C$ is defined as in \cref{lem:concentrationlemmapart1}. In fact, by this same lemma, we have on the event therein and $\mathcal{E}_{\text{\cref{lem:Zstgoodproperties}}}$ it holds that
\begin{align}
     L_{\lambda}^{(n)}\big( \| \bm{W} \|_F \leq R \cap \bm{W} + \bm{M} \succcurlyeq 0 \cap \mathrm{Rank}(\bm{W} + \bm{M}) \leq r \big) &\geq   L_{\lambda}^{(n)}\big( \| \bm{W} \|_F \leq R \cap \bm{W} + \bm{M} \succcurlyeq 0  \big) \\
     &\geq L_{\lambda}^* - C \widetilde \ensuremath{\varepsilon}\sqrt{\gamma_n}.
\end{align}
\\
 \ \noindent
 \textbf{Step 2: The bound \eqref{eq:thinktoprove1}.} We have that
on these events
    \begin{align}
    L_{\lambda}^* + C \sqrt{\gamma_n} \widetilde \ensuremath{\varepsilon} \geq h(\bm{\widehat U}) &\geq L_{\lambda}^{(n)}\big( \|\bm{W}\|_F \leq R \cap PSD \cap \mathrm{rank}(\bm{W} + \bm{M}) \leq r \big) \\
    &\geq L_{\lambda}^{(n)}\big( \|\bm{W}\|_F \leq R \cap PSD \big), 
    \end{align}
    which proves \eqref{eq:thinktoprove1} whenever $ C\widetilde \ensuremath{\varepsilon} \sqrt{\gamma_n} = C'  \ensuremath{\varepsilon}^2$, which we will show is valid at the end of Step 3 below.  
 \\ \ \\
 \noindent
 \textbf{Step 3: The bound \eqref{eq:thingtoprove}.}   The bound \eqref{eq:thingtoprove} will require a little more analysis.   
    Define the regions
\begin{align}
    \mathcal{R}_1 := \{ \bm{U} : \| \bm{U} - \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}}\|_F \leq \frac{1}{8 \| \bm{U}^* \|} R \}; \\
    \mathcal{R}_2 := \{ \bm{U} : \| \bm{UU}^{\top} - \bm{\widehat U} \bm{\widehat U}^{\top} \|_F \leq R \}.
\end{align}
We claim that have the containment $\mathcal{R}_1 \subset \mathcal{R}_2$ on the event $\mathcal{E}_{\text{\cref{lem:Zstgoodproperties}}}$.  
In order to see this, observe that for any $\bm{U} \in \mathcal{R}_1$, 
\begin{align}
    \| \bm{UU}^{\top} - \bm{\widehat U} \bm{\widehat U} \|_F \leq \big( \| \bm{U} \| + \| \bm{\widehat U} \| \big)  \frac{1}{8 \| \bm{U}^* \|} R.
\end{align}
On the event $\mathcal{E}_{\text{\cref{lem:Zstgoodproperties}}}$ it holds that $\|\bm{Z}_{{\sf ST}}^{(\lambda)} \| \leq 2 \| \bm{M}\|$.  Consequently, on this same event, we have that $\|\bm{\widehat U}\| \leq 2 \|\bm{U}^* \|$, since $\|\bm{\widehat U}\|^2 = \| \bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*)\|$.  
Furthermore, we have that by virtue of $\bm{U} \in \mathcal{R}_1$,
\begin{align}
    \| \bm{U} \| &\leq \| \bm{U} \mathcal{O}_{\bm{U},\bm{\widehat U}} - \bm{\widehat U} \| + \| \bm{\widehat U} \| \leq  \frac{1}{8 \|\bm{U}^* \|} R + 2 \|\bm{U}^* \| \\
    &\leq  \frac{\lambda_{\min}(\bm{M})}{8 \sqrt{\lambda_{\max}(\bm{M})}} + 2 \|\bm{U}^* \|\leq 4 \| \bm{U}^* \|.
\end{align}
Consequently,
\begin{align}
     \| \bm{UU}^{\top} - \bm{\widehat U} \bm{\widehat U} \|_F \leq \big( \| \bm{U} \| + \| \bm{\widehat U} \| \big)  \frac{1}{8 \| \bm{U}^* \|} R \leq R.
\end{align}
Therefore, $\mathcal{R}_1 \subset \mathcal{R}_2$. Note that we have used the implicit assumption that $\lambda_r \geq C_1 \sigma \sqrt{r}$ for some sufficiently large constant $C_1$.  

We will now show that $h$ is strongly convex on the region $\mathcal{R}_2$ for a particular parameter $\alpha$.  By \cref{lem:hstronglyconvex} on the event $\mathcal{E}_h$, $h$ is strongly convex with the parameter 
\begin{align}
    \alpha =  \frac{\lambda_{\min}(\bm{M})}{32 dr} + 2 \frac{\lambda}{dr},
\end{align}
provided $\bm{U}$ lies in the region $\mathcal{R}$ defined via
\begin{align}
    \mathcal{R} := \bigg\{ \bm{U}: \| \bm{U} - \bm{U}^* \mathcal{O}_{\bm{U}^*, \bm{U}} \| \leq \frac{c}{\kappa(\bm{M})} \|\bm{U}^* \|.\bigg\} 
\end{align}
We will show that $\mathcal{R}_2 \subset \mathcal{R}$. 
It holds that $\|\bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*) - \bm{M} \|_F \leq C \sigma \sqrt{dr}$ on the event $\mathcal{E}_{\text{\cref{lem:Zstgoodproperties}}}$ by appropriately choosing $s = O(1)$ in the statement therein.  (See, for example, the proof of \cref{lem:h_yhat_bounded}.)  We then have that 
\begin{align}
    \| \bm{UU}^{\top} - \bm{U}^* \bm{U}^{*\top} \|_F &\leq R + \|  \bm{U}^* \bm{U}^{*\top} -\bm{\widehat U \widehat U}^{\top} \|_F = R + \| \bm{Z}_{{\sf ST}}^{(\lambda)} - \bm{M} \|_F \\
    &\leq C' \sigma \sqrt{dr}.
\end{align} 
As a consequence, we have that
\begin{align}
    \| \bm{U} - \bm{U}^* \mathcal{O}_{\bm{U}^*,\bm{U}} \| \leq  \frac{c_0 C'}{\sqrt{\lambda_{\min}}} \sigma \sqrt{dr} 
    &\leq \frac{c}{\kappa(\bm{M})} \| \bm{U}^* \|,
\end{align}
which holds as long as  $\lambda_{\min}(\bm{M})/\sigma \geq C_1 \kappa \sqrt{dr}$, for some appropriately large constant $C_1$, which holds according to \cref{ass1}.  


Consequently, on the event $\mathcal{E}_1 \cap \mathcal{E}_2 \cap \mathcal{E}_{\text{\cref{lem:Zstgoodproperties}}} \cap \mathcal{E}_h$, 
\begin{align}
  h(\bm{\widehat U}) &=  L_{\lambda}^{(n)}( \bm{\widehat W}) \leq  L_{\lambda}^{(n)}\big( \| \bm{W} \|_F \leq R \cap \bm{W} + \bm{M} \succcurlyeq 0 \cap \mathrm{rank}(\bm{W} + \bm{M}) \leq r\big) + 2 C \widetilde\ensuremath{\varepsilon} \sqrt{\gamma_n} \\
  &= \min_{\mathcal{R}_2} h(\bm{U}) + 2C \widetilde\ensuremath{\varepsilon} \sqrt{\gamma_n} \\
  &\leq \min_{\mathcal{R}_1} h(\bm{U}) + 2C \widetilde\ensuremath{\varepsilon} \sqrt{\gamma_n} \\
  &= \min_{\bm{U}: \| \bm{U} - \bm{U}^* \mathcal{O}_{\bm{U}^*,\bm{U}} \|_F \leq \frac{1}{8 \| \bm{U}^* \|} R} h(\bm{U}) + 2 C \widetilde\ensuremath{\varepsilon} \sqrt{\gamma_n}, \label{contradictionbb}
\end{align}
were the final bound holds from the containment $\mathcal{R}_1 \subset \mathcal{R}_2$.   By \cref{lem:miolaneb1analogue}, since $h$ is strongly convex on the region $\mathcal{R}_2$ with parameter $\alpha$, for any $\bm{U} \in \mathbb{B}(\bm{\widehat U}, \frac{R}{8\|\bm{U}^*\|} )$, it holds that $\| \bm{U}  \mathcal{O}_{\bm{U},\bm{\widehat U}}- \bm{\widehat U}\|_F^2 \leq \frac{8 C \sqrt{\gamma_n} \widetilde\ensuremath{\varepsilon}}{\alpha}$. 
In addition, for any $\bm{U} \in \mathbb{B}\big( \bm{\widehat U}, \frac{R}{8\|\bm{U}^*\|} \big)$, we have that
\begin{align}
    \| \bm{UU}^{\top} - \bm{\widehat U} \bm{\widehat U}^{\top} \|_F \leq \big( \|\bm{U}\| + \| \bm{\widehat U} \| \big) \| \bm{U} - \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}} \|_F 
\leq  4 \| \bm{U}^* \| \| \bm{U} - \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}} \|_F.
\end{align}
Consequently, if
\begin{align}
    \frac{\| \bm{UU}^{\top} - \bm{\widehat U \widehat U}^{\top} \|_F}{\sqrt{dr}} > \frac{\ensuremath{\varepsilon}}{2},
\end{align}
then it holds that 
\begin{align}
    \| \bm{U} - \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}} \|_F \geq 
       \frac{1}{4\| \bm{U}^* \|} \| \bm{UU}^{\top} - \bm{\widehat U\widehat U}^{\top} \|_F >  \frac{\ensuremath{\varepsilon} \sqrt{dr}}{ 4\| \bm{U}^* \|} .
\end{align}
The contrapositive of \cref{lem:miolaneb1analogue} implies that for $\bm{U}$ as above, it must hold that
\begin{align}
    h(\bm{U}) > \min_{\bm{U} : \| \bm{U} - \bm{U}^* \mathcal{O}_{\bm{U}^*,\bm{U}} \|_F \leq \frac{R}{8 \| \bm{U}^* \|}}h(\bm{U}) + \bigg(\frac{\ensuremath{\varepsilon} \sqrt{dr}}{ 4\| \bm{U}^* \|}\bigg)^2 \frac{\alpha}{8} \label{hguy}
\end{align}
Define $\widetilde \ensuremath{\varepsilon}$ via
\begin{align}
     \widetilde \ensuremath{\varepsilon} = \frac{\ensuremath{\varepsilon}^2 dr \alpha }{128 C \sqrt{\gamma}_n \| \bm{U}^*\|^2}.
\end{align}
Then the display equation \eqref{hguy} simplifies to
\begin{align}
    h(\bm{U}) > \min_{\bm{U} : \|\bm{U - U^*} \mathcal{O}_{\bm{U}^*,\bm{U}}\|_F \leq \frac{R}{8\|\bm{U}^*\|} } h(\bm{U}) + C \sqrt{\gamma_n} \widetilde \ensuremath{\varepsilon},
\end{align}
which is a contradiction to \eqref{contradictionbb}.  Recalling the definition of $\alpha$ from earlier, we have that 
\begin{align}
    C \sqrt{\gamma_n} \widetilde \ensuremath{\varepsilon} &= \frac{\ensuremath{\varepsilon}^2dr}{128 \| \bm{U}^* \|^2} \bigg( \frac{\lambda_{\min}(\bm{M})}{32 dr} + 2 \frac{\lambda}{dr} \bigg) \\
    &= \frac{\ensuremath{\varepsilon}^2}{128} \bigg( \frac{1}{32 \kappa} + 2 \frac{\lambda}{\|\bm{M}\|} \bigg) = C \ensuremath{\varepsilon}^2.  
    \end{align}
which justifies the previous choice of $\widetilde \ensuremath{\varepsilon}$ from the previous step.  
In particular, on these events it holds that
\begin{align}
    L_{\lambda}^{(n)} \bigg( \mathbb{B}_{\ensuremath{\varepsilon}/2}^c( \bm{\widehat W}/\sqrt{dr}) \cap \mathrm{rank}(W + M) \leq r \cap \| \bm{W} \|_F \leq R \bigg) > L_{\lambda}^* + 2 \ensuremath{\varepsilon}^2 
    \label{eq:thingtoproveproven}
    \end{align}
which is precisely  \eqref{eq:thingtoprove}.  This algebra also verifies the choice of $\widetilde \ensuremath{\varepsilon}$ from the previous step of the proof.
 \\ \ \\ \noindent
 \textbf{Step 4: Tabulating probabilities}. 
We bound each event in turn. 
\begin{itemize}
\item \textbf{The events $\mathcal{E}_{\cref{lem:Zstgoodproperties}}$ and $\mathcal{E}_h$}: The first event holds with probability at least $1 - C\exp(- c d)$.  Furthermore, by \cref{lem:Eh_highprob}, 
