    L_{\lambda}^* + C \sqrt{\gamma_n} \widetilde \ensuremath{\varepsilon} \geq h(\bm{\widehat U}) &\geq L_{\lambda}^{(n)}\big( \|\bm{W}\|_F \leq R \cap PSD \cap \mathrm{rank}(\bm{W} + \bm{M}) \leq r \big) \\
