      L_{\lambda}^{(n)}\big( \bm{Z}_{{\sf ST}}^{(\lambda/\zeta^*)}(\tau^*) - \bm{M} \big) \leq L_{\lambda}^* + s+ C \exp(- c dr)
\end{align}

