            L_{\lambda}^{(n)} \bigg( \|\bm{W}\|\leq R; \bm{W + M} \succcurlyeq 0 \bigg) &\geq L_{\lambda}^* - C t \sqrt{\gamma_n} 
    \end{align}

\begin{align}
        L_{\lambda}^{(n)} \bigg( \|\bm{W}\|_F \leq R; \bm{W} + \bm{M} \succcurlyeq 0; \mathrm{rank}(\bm{W} + \bm{M}) \leq r \bigg) \geq  L_{\lambda}^{(n)} \bigg( \|\bm{W}\|\leq R; \bm{W + M} \succcurlyeq 0 \bigg)
    \end{align}

\begin{align}
    1 - O\bigg( \exp( - c d) +  \exp( - c dr) + \exp( - c n) + \frac{1}{\ensuremath{\varepsilon}^2} \exp(-c dr \ensuremath{\varepsilon}^4 ) - \exp( - \frac{(dr)^2}{n} \ensuremath{\varepsilon}^4) \bigg),
\end{align}

The proof of this result resembles the proof of Lemma B.3 in \citet{celentano_lasso_2023}. Throughout we assume implicitly that $\bm{W} \succcurlyeq -\bm{M}$.  
Throughout the proof, denote $R := C \sigma \sqrt{dr}$. 
We observe that we can rewrite $L_{\lambda}(\mathcal{W})$ (see the derivation in \eqref{L_lambda_derivation}) via
\begin{align}
    L_{\lambda}(\bm{W}) &:= \max_{\beta > 0}  \bigg(\gamma_n \sqrt{\frac{\| \bm{W} \|_F^2 }{n} + \sigma^2} \frac{\|\bm{g}\|}{\sqrt{n}} - \frac{\langle \bm{H},\bm{W}\rangle}{dr} \bigg) \beta - \gamma_n \frac{\beta^2}{2} + \frac{\lambda}{dr} \big\{ \|\bm{W} + \bm{M} \|_* - \| \bm{M}\|_* \big\} \\
    &=: \max_{\beta \geq 0} \ell_{\lambda}(\bm{W},\beta; \bm{g}) \\
    &\geq \ell_{\lambda}(\bm{W}, \beta^*; \bm{g}).
\end{align}
Define the event
\begin{align}
    \mathcal{E}_{{\bm{g}}} := \bigg\{ \bigg| \frac{\|\bm{g}\|}{\sqrt{n}} - 1 \bigg| \leq t /\sqrt{\gamma_n} \bigg\}.
\end{align}
Since $\bm{g} \mapsto \frac{\|\bm{g}\|}{\sqrt{n}}$ is a 1-Lipschitz function, we have that $\mathbb{P}\big(\mathcal{E}_{{\bm{g}}}\big) \geq 1 - \exp( -c dr t^2)$ for all $t > 0$.  
Denote the modified objective
\begin{align}
    \widetilde\ell_{\lambda}(\bm{W},\beta) := \bigg(\gamma_n \sqrt{\frac{\| \bm{W} \|_F^2 }{n} + \sigma^2} - \frac{\langle \bm{H},\bm{W}\rangle}{dr} \bigg) \beta - \gamma_n \frac{\beta^2}{2} + \frac{\lambda}{dr} \big\{ \|\bm{W} + \bm{M} \|_* - \| \bm{M}\|_* \big\}.
\end{align}
If  $\|\bm{W}\|_F \leq R$, it holds that on  the event $\mathcal{E}_{\bm{g}}$,
\begin{align}
    \big| \ell_{\lambda}(\bm{W},\beta^*)- \widetilde \ell_{\lambda}(\bm{W},\beta) \big| \leq \beta_{\max} \gamma_n^{1/2} t   \sqrt{\frac{R^2}{n} + \sigma^2} \leq 2C \gamma_n^{1/2} t \sigma.
\end{align}
Consequently, on this event
\begin{align}
    \min_{\|\bm{W}\|_F \leq R }L_{\lambda}(\bm{W}) &= \min_{\|\bm{W}\|_F \leq R} \max_{\beta \geq 0} \ell(\bm{W},\beta) \geq \min_{\| \bm{W}\|_F \leq R} \ell(\bm{W}, \beta^*) \\
    &\geq \min_{\|\bm{W}\|_F \leq R }\widetilde \ell(\bm{W},\beta^*) - 2\beta_{\max} \gamma_n^{1/2} \ensuremath{\varepsilon} \sigma. 
\end{align}
Next, for every $\tau \in [\sigma ,\sqrt{\sigma^2 + \frac{R^2}{n}}]$, the function
\begin{align}
    \bm{H} \mapsto \min_{\|\bm{W}\|_F \leq R} \bigg\{\frac{\gamma_n \beta^*\|\bm{W}\|_F^2}{2\tau n} - \frac{\gamma_n \beta^*}{n} \langle \bm{H},\bm{W} \rangle + \frac{\lambda}{dr} \{ \|\bm{W} + \bm{M} \|_* - \| \bm{M} \|_* \} \bigg\}
\end{align}
is $\frac{\gamma_n \beta^*}{n} R$-Lipschitz, and hence so is $\bm{H} \mapsto F(\tau,\bm{H})$.  Consequently, 
\begin{align}
    \mathbb{P}\bigg\{ \bigg| F(\tau,\bm{H}) - \mathbb{E} F(\tau,\bm{H}) \bigg| > \ensuremath{\varepsilon} \frac{R \gamma_n}{\sqrt{n}} \bigg\} &\leq 2 \exp\bigg( - c \frac{n}{( \beta^*)^2} \ensuremath{\varepsilon}^2 \bigg).
\end{align}
Furthermore, since $\tau \mapsto F(\tau,\bm{H})$ is $\big(\beta^* \gamma_n \big[ \frac{R^2}{n \sigma} + \frac{1}{2} + \frac{\sqrt{\sigma^2 + \frac{R^2}{n}}}{2}\big] \big) \leq C \beta^* \gamma_n (\sigma + 1)$-Lipschitz, we can conclude via an $\ensuremath{\varepsilon}$-net argument that there exists constants depending on $\beta^*,\sigma$ such that
\begin{align}
    \mathbb{P}\bigg\{ \sup_{\tau \in [\sigma, \sqrt{\sigma^2 + \frac{R^2}{n}}]} \bigg| F(\tau,\bm{H}) - \mathbb{E}F(\tau,\bm{H}) \bigg| \leq  \ensuremath{\varepsilon} \frac{R \gamma_n}{\sqrt{n}} \bigg\} &\geq 1 - \frac{C \gamma_n^{3/2}}{\ensuremath{\varepsilon} } \exp\bigg( - c n\ensuremath{\varepsilon}^2 \bigg) \\
    &\geq 1 - \frac{C}{\ensuremath{\varepsilon} } \exp\bigg( - c  n \ensuremath{\varepsilon}^2 \bigg),
\end{align}
since $\gamma_n \geq 1$.  Assuming this event holds we have that
\begin{align}
    \min_{\|\bm{W}\|_F \leq R} \widetilde \ell(\bm{W},\beta^*) &\geq \min_{\tau\in [ \sigma,\sqrt{\sigma^2 + R^2}]} \mathbb{E} F(\tau,\bm{H}) - \ensuremath{\varepsilon} \frac{R\gamma_n}{\sqrt{n}}.
\end{align}
Recalling that $R = C \sigma \sqrt{dr}$, it holds that $\ensuremath{\varepsilon} \frac{R \gamma_n}{\sqrt{n}} =C \ensuremath{\varepsilon} \sigma \sqrt{\gamma_n}$.  Furthermore, observe that 
\begin{align}
    \mathbb{E} F(\tau,\bm{H}) &\geq  \min_{\tau \in [\sigma ,\sqrt{\sigma^2 + R^2}]}  \bigg\{ \bigg( \frac{\sigma^2}{2\tau} + \frac{\tau}{2} \bigg) \beta^* \gamma_n - \frac{\gamma_n(\beta^*)^2}{2}\\
    &\quad +  \mathbb{E} \min_{\bm{W}} \bigg\{ \frac{\gamma_n\beta^*}{2\tau n} \| \bm{W}\|_F^2 - \frac{\gamma_n\beta^*}{n} \langle \bm{H,W} \rangle + \frac{\lambda}{dr} \big\{ \| \bm{W} + \bm{M}\|_* - \bm{M}\|_*\big\} \bigg\} \bigg\} \\
    &=\min_{\tau \in [\sigma ,\sqrt{\sigma^2 + R^2}]} \psi_{\lambda}^*(\tau,\beta^*) \\
    &\geq  \psi_{\lambda}^*(\tau^*,\beta^*) = L_\lambda^*
\end{align}
where $\psi_{\lambda}^*(\tau,\beta^*)$ is defined in \eqref{psistardef}.  Combining these arguments, on these events we have that
\begin{align}
    L_{\lambda}^{(n)} \geq L_{\lambda}^* - C \ensuremath{\varepsilon} \sqrt{\gamma_n} 
\end{align}
which holds cumulatively with probability at least
\begin{align}
    1 -     \frac{1}{\ensuremath{\varepsilon}} \exp( - c n \ensuremath{\varepsilon}^2) - \exp(-dr \ensuremath{\varepsilon}^2 ).
\end{align}

define
\begin{align}
    \tau(\bm{U}) :&= \sqrt{\frac{\|\bm{UU}^{\top} - \bm{M}\|_F^2}{n} + \sigma^2},
\end{align}
which implies that
\begin{align}
    f(\bm{U}) &= \sqrt{\frac{\|\bm{UU}^{\top} - \bm{M}\|_F^2}{n} + \sigma^2} \frac{\|\bm{g}\|}{\sqrt{n}} - \frac{\langle \bm{H}, \bm{UU}^{\top} - \bm{M} \rangle}{n} \equiv \tau(\bm{U}) \frac{\|\bm{g}\|}{\sqrt{n}} - \frac{\langle \bm{H}, \bm{UU}^{\top} - \bm{M} \rangle}{n}; \\
    h(\bm{U}) &= \frac{\gamma_n}{2} ( f(\bm{U}))_+^2 + \frac{\lambda}{dr} \big\{ \|\bm{U}\|_F^2 - \|\bm{M}\|_* \big\}.

 \label{lem:hessiancalculation}
It holds that
\begin{align}
    \nabla^2 h(\bm{U})[ \bm{V}, \bm{V}] &=  \frac{4 \gamma_n}{n^2 \tau^2(\bm{U})} \frac{\|\bm{g}\|}{\sqrt{n}} \bigg( \frac{\|\bm{g}\|}{\sqrt{n}} - \frac{f(\bm{U})_+}{\tau(\bm{U})} \bigg) \bigg \langle \big( \bm{UU}^{\top} - \bm{M}\big) \bm{U}, \bm{V} \bigg \rangle^2 \\
    &\quad + \frac{4\gamma_n}{n^2} \bigg \langle \bm{HU}, \bm{V} \bigg\rangle^2 \\
    &\quad + \frac{4 \gamma_n}{n^2 \tau(\bm{U})} \frac{\|\bm{g}\|}{\sqrt{n}} \bigg( \frac{f(\bm{U})_+}{\tau^2(\bm{U})} - 2 \bigg) \bigg \langle \bm{HU}, \bm{V} \bigg \rangle \bigg \langle \big( \bm{UU}^{\top} - \bm{M} \big) \bm{U}, \bm{V} \bigg \rangle \\
    &\quad +\gamma_n f(\bm{U})_+ 2\tau(\bm{U})^{-1} \frac{\|\bm{g}\|}{\sqrt{n}}  \bigg\langle \bigg(  \frac{\big(  \bm{VU}^{\top} +  \bm{UV}^{\top} \big) }{n}  \bigg)\bm{U}, \bm{V} \bigg \rangle \\
    &\quad +\gamma_n f(\bm{U})_+ 2\tau(\bm{U})^{-1} \frac{\|\bm{g}\|}{\sqrt{n}}  \bigg\langle \bigg(  \frac{\bm{UU}^{\top} - \bm{M}- \bm{H}}{n}  \bigg) \bm{V} , \bm{V} \bigg \rangle \\
    &\quad + 2 \frac{\lambda}{dr} \| \bm{V} \|_F^2.
\end{align}

Recall we define the event
\begin{align}
    \mathcal{E}_h &:= \bigg\{ \big| \langle \bm{H}, \bm{Q} \rangle \big| \leq C \sqrt{dr} \| \bm{Q} \|_F \text{ for all matrices $\bm{Q}$ of rank at most $2r$} \bigg\} \cap \big\{ \frac{1}{2} \leq  \frac{\|\bm{g}\|}{\sqrt{n}} \leq 2 \big\} \cap \bigg\{ \| \bm{H} \| \leq 3 \sqrt{d} \bigg\}.
\end{align}
We decompose the hessian by \cref{lem:hessiancalculation} via
\begin{align}
    \nabla^2 h(\bm{U})[\bm{V}, \bm{V}] := T_1 + T_2 + T_3 + T_4 + T_5 + T_6
\end{align}
where
\begin{align}
 \\   T_1 &:= \frac{4 \gamma_n}{n^2 \tau^2(\bm{U})} \frac{\|\bm{g}\|}{\sqrt{n}} \bigg( \frac{\|\bm{g}\|}{\sqrt{n}} - \frac{f(\bm{U})_+}{\tau(\bm{U})} \bigg) \bigg \langle \big( \bm{UU}^{\top} - \bm{M}\big) \bm{U}, \bm{V} \bigg \rangle^2\\  
 T_2 &:= \frac{4\gamma_n}{n^2} \bigg \langle \bm{HU}, \bm{V} \bigg\rangle^2 \\  
 T_3 &:= \frac{4 \gamma_n}{n^2 \tau(\bm{U})} \frac{\|\bm{g}\|}{\sqrt{n}} \bigg( \frac{f(\bm{U})_+}{\tau^2(\bm{U})} - 2 \bigg) \bigg \langle \bm{HU}, \bm{V} \bigg \rangle \bigg \langle \big( \bm{UU}^{\top} - \bm{M} \big) \bm{U}, \bm{V} \bigg \rangle \\
 T_4 &:= \gamma_n f(\bm{U})_+ 2\tau(\bm{U})^{-1} \frac{\|\bm{g}\|}{\sqrt{n}}  \bigg\langle \bigg(  \frac{\big(  \bm{VU}^{\top} +  \bm{UV}^{\top} \big) }{n}  \bigg)\bm{U}, \bm{V} \bigg \rangle \\   
 T_5 &:= \gamma_n f(\bm{U})_+ 2\tau(\bm{U})^{-1} \frac{\|\bm{g}\|}{\sqrt{n}}  \bigg\langle \bigg(  \frac{\bm{UU}^{\top} - \bm{M}- \bm{H}}{n}  \bigg) \bm{V} , \bm{V} \bigg \rangle \\   
 T_6 &:=  2 \frac{\lambda}{dr} \| \bm{V} \|_F^2.
\end{align}
We will show that some of the terms above are small-order terms on the event $\mathcal{E}_h$, and then some of the terms provide a lower bound.
\begin{itemize}
    \item \textbf{The term $T_1$}:  Observe that if $f(\bm{U}) > 0$,
\begin{align}
    \frac{\|\bm{g}\|}{\sqrt{n}} - \frac{f(\bm{U})_+}{\tau(\bm{U})} &= \frac{\langle \bm{H}, \bm{UU}^{\top} - \bm{M} \rangle}{n \tau(\bm{U})}.
\end{align}
In addition, we have that
\begin{align}
    \| \bm{UU}^{\top} - \bm{M} \|_F/\sqrt{n} \leq \tau(\bm{U}).
\end{align}
Consequently, we have that
\begin{align}
    T_1 &\leq \frac{4 \gamma_n}{n} \frac{\|\bm{g}\|}{\sqrt{n}}\bigg| \frac{\langle \bm{H},\bm{UU}^{\top} - \bm{M} \rangle \rangle}{n \tau(\bm{U})} \bigg| \frac{\|\bm{UU}^{\top} - \bm{M}\|_F^2 \|\bm{U}\|^2 \|\bm{V} \|_F^2}{n \tau^2(\bm{U})} \\
    &\leq \frac{4}{dr} \frac{\|\bm{g}\|}{\sqrt{n}}\bigg| \frac{\langle \bm{H},\bm{UU}^{\top} - \bm{M} \rangle \rangle}{n \tau(\bm{U})} \bigg| \| \bm{U}\|^2 \|\bm{V} \|_F^2.
\end{align}
Note that on the event $\mathcal{E}_h$,
\begin{align}
    \bigg| \bigg\langle \bm{H}, \bm{UU}^{\top} - \bm{M} \bigg \rangle \bigg| \leq C \sqrt{dr} \| \bm{UU}^{\top} - \bm{M} \|_F; \qquad  \frac{\|\bm{g}\|}{\sqrt{n}} \leq 2.   \end{align}
Therefore,
\begin{align}
    T_1 &\leq \frac{8C}{\sqrt{ndr}} \frac{\|\bm{UU}^{\top} - \bm{M}\|_F}{\sqrt{n} \tau(\bm{U})} \|\bm{U} \|^2 \|\bm{V} \|_F^2 \\
    &\leq \frac{8C}{\sqrt{ndr}}\|\bm{U} \|^2 \|\bm{V} \|_F^2.
\end{align}
Furthermore, when $\|\bm{U} - \bm{U}^* \mathcal{O}_{\bm{U}^*,\bm{U}} \| \leq \frac{c}{\kappa(\bm{M})} \| \bm{U}^* \|$, we have that $\|\bm{U}\| \leq 2 \|\bm{U}^*\|$.  Therefore,
\begin{align}
    T_1 \leq \frac{16C}{\sqrt{ndr}} \|\bm{M} \| \|\bm{V} \|_F^2 = \frac{16 C \kappa}{\sqrt{ndr}} \lambda_{\min}(\bm{M}) \|\bm{V} \|_F^2.
\end{align}


\item \textbf{The term $T_2$:} We note that the term $T_2$ is a square of something times a nonnegative number, whence $T_2 \geq 0$.  
\item \textbf{The term $T_3$}: We will upper bound $T_3$.  Recall that if $f(\bm{U})_+ > 0$ then
\begin{align}
    f(\bm{U})_+ = \tau(\bm{U}) \frac{\|\bm{g}\|}{\sqrt{n}} - \frac{\langle \bm{H}, \bm{UU}^{\top} - \bm{M}\rangle}{n}.
\end{align}
We have that
\begin{align}
     T_3 &:= \frac{4 \gamma_n}{n^2 \tau(\bm{U})} \frac{\|\bm{g}\|}{\sqrt{n}} \bigg( \frac{f(\bm{U})_+}{\tau^2(\bm{U})} - 2 \bigg) \bigg \langle \bm{HU}, \bm{V} \bigg \rangle \bigg \langle \big( \bm{UU}^{\top} - \bm{M} \big) \bm{U}, \bm{V} \bigg \rangle \\
     &\leq \frac{4}{ndr \tau(\bm{U})} \frac{\|\bm{g}\|}{\sqrt{n}} \bigg( \frac{\tau(\bm{U}) \frac{\|\bm{g}\|}{\sqrt{n}} - \frac{\langle \bm{H}, \bm{UU}^{\top} - \bm{M}\rangle}{n}}{\tau^2(\bm{U})} - 2 \bigg) \bigg \langle \bm{HU}, \bm{V} \bigg \rangle \bigg \langle \big( \bm{UU}^{\top} - \bm{M} \big) \bm{U}, \bm{V} \bigg \rangle \\
     &\leq \frac{4}{ndr \tau(\bm{U})} \bigg( \frac{1}{\tau(\bm{U})} + \bigg| \frac{\langle \bm{H}, \bm{UU}^{\top} - \bm{M} \rangle}{n \tau^2(\bm{U})}\bigg| + 2 \bigg) \bigg| \bigg\langle \bm{HU}, \bm{V} \bigg\rangle \bigg| \bigg\langle (\bm{UU}^{\top} - \bm{M}) \bm{U} , \bm{V} \bigg \rangle \bigg| \\
     &\lesssim \frac{1}{ndr \tau(\bm{U})} \bigg( \frac{1}{\tau(\bm{U})} + \bigg| \frac{\langle \bm{H}, \bm{UU}^{\top} - \bm{M} \rangle}{n \tau^2(\bm{U})}\bigg| + 2 \bigg) \bigg| \bigg \langle \bm{HU}, \bm{V} \bigg \rangle \bigg| \| (\bm{UU}^{\top} - \bm{M} )\|_F \|\bm{V} \|_F \| \bm{U}\|.
\end{align}
On the event $\mathcal{E}_h$ it holds that 
\begin{align}
    \bigg| \bigg\langle \bm{H}, \bm{UU}^{\top} - \bm{M} \bigg\rangle \bigg| &\lesssim \sqrt{dr} \| \bm{UU}^{\top} - \bm{M} \|_F; \\
    \bigg| \bigg\langle \bm{HU}, \bm{V} \bigg\rangle \bigg| &\lesssim \sqrt{dr} \| \bm{VU}^{\top} \|_F \lesssim \sqrt{dr} \| \bm{V} \|_F \| \bm{U}\|.
\end{align}
Plugging this in above yields
\begin{align}
    T_3 \lesssim \frac{\| \bm{UU}^{\top} - \bm{M}\|_F}{n \sqrt{dr} \tau(\bm{U})} \bigg( \frac{1}{\tau(\bm{U})} + \frac{\sqrt{dr} \| \bm{UU}^{\top} - \bm{M}\|_F}{n\tau^2(\bm{U})} + 2 \bigg) \| \bm{V} \|_F^2 \| \bm{U} \|^2.
\end{align}
We also recall that 
\begin{align}
    \frac{ \| \bm{UU}^{\top} - \bm{M}\|_F}{\sqrt{n} \tau(\bm{U})} \leq 1.
\end{align}
Therefore,
\begin{align}
    T_3 &\lesssim \frac{\| \bm{V}\|_F^2 \| \bm{U}\|^2}{\sqrt{ndr}} \bigg( \frac{1}{\tau(\bm{U})} + \frac{\sqrt{dr}}{\sqrt{n} \tau(\bm{U})} + 2 \bigg) \\
    &\lesssim \frac{\|\bm{U}\|^2 \|\bm{V}\|_F^2}{\sqrt{ndr}} \\
    &\lesssim \|\bm{V}\|_F^2 \frac{\kappa \lambda_{\min}(\bm{M})}{\sqrt{ndr}}
\end{align}
since $\tau(\bm{U}) \geq \sigma \geq \sigma_{\min} > 0$ and $\|\bm{U}\|^2 \lesssim \| \bm{M}\| \lesssim \kappa \lambda_{\min}(\bm{M})$.  

\item \textbf{The term $T_4$:} We will lower bound $T_4$. We have that
\begin{align}
    T_4 &= \frac{2}{dr \tau(\bm{U})} f(\bm{U})_+ \frac{\|\bm{g}\|}{\sqrt{n}} \bigg \langle \bigg( \bm{VU}^{\top} + \bm{UV}^{\top} \bigg) \bm{U}, \bm{V} \bigg \rangle \\
    &\geq \frac{f(\bm{U})_+}{dr \tau(\bm{U})}  \bigg \langle \bigg( \bm{VU}^{\top} + \bm{UV}^{\top} \bigg) \bm{U}, \bm{V} \bigg \rangle.
\end{align}
Next, we note that on the event $\mathcal{E}_h$ it holds that
\begin{align}
    \bigg| \langle \bm{H}, \bm{UU}^{\top} - \bm{M} \rangle \bigg| \leq C \sqrt{dr} \| \bm{UU}^{\top} - \bm{M} \|_F.
\end{align}
In addition, $\tau(\bm{U}) \geq \frac{\|\bm{UU}^{\top} - \bm{M}\|_F}{\sqrt{n}} $.  Together, these conditions imply that
\begin{align}
    f(\bm{U}) &= \tau(\bm{U}) \frac{\|\bm{g}\|}{\sqrt{n}} - - \frac{C \sqrt{dr}}{\sqrt{n}} \frac{\|\bm{UU}^{\top} - \bm{M}\|_F}{\sqrt{n}}\\
    &\geq .5 \sigma + .5 \frac{\|\bm{UU}^{\top} - \bm{M}\|_F}{\sqrt{n}} - \frac{C \sqrt{dr}}{\sqrt{n}} \frac{\|\bm{UU}^{\top} - \bm{M}\|_F}{\sqrt{n}} \\
    &= .5\sigma + \bigg( \frac{1}{2} - C\sqrt{\frac{dr}{n}} \bigg) \frac{\|\bm{UU}^{\top} - \bm{M}\|_F}{\sqrt{n}} \\
    &\geq \frac{1}{4} \sigma + \frac{1}{4} \frac{\|\bm{UU}^{\top} - \bm{M}\|_F}{\sqrt{n}},
\end{align}
where the final inequality holds by \cref{ass2} as long as $C_3$ is sufficiently large.  Therefore, it holds that $\frac{f(\bm{U})_+}{\tau(\bm{U})} \geq \frac{1}{4}$, and hence that 
\begin{align}
    T_4 &\geq     
    \frac{1}{4dr} \bigg \langle \bigg( \bm{VU}^{\top} + \bm{UV}^{\top} \bigg) \bm{U}, \bm{V} \bigg \rangle. 
\end{align}
We now analyze the quantity $\bigg \langle \bigg( \bm{VU}^{\top} + \bm{UV}^{\top} \bigg) \bm{U}, \bm{V} \bigg \rangle$.  Observe that we can rewrite this quantity as
\begin{align}
    \| \bm{U}^{\top} \bm{V} \|_F^2 + {\sf Tr}\big[ \bm{UV}^{\top} \bm{UV}^{\top} \big] \geq \lambda_{\min}(\bm{U})^2 \| \bm{V} \|_F^2 + {\sf Tr}\big[ \bm{UV}^{\top} \bm{UV}^{\top} \big].
\end{align}
Weyl's inequality implies that $\lambda_{\min}(\bm{U})^2 \geq \frac{1}{4} \lambda_{\min}(\bm{M})$ provided $c$ smaller than some absolute constant.  

To complete the lower bound, we note that $\bm{V} = \bm{U - U'}\mathcal{O}$, where $\mathcal{O}$ is the Frobenius-optimal orthogonal matrix aligning $\bm{U}$ and $\bm{U}'$. Consequently, we observe that
\begin{align}
    {\sf Tr}\big[ \bm{UV}^{\top} \bm{UV}^{\top} \big] &= {\sf Tr}\big[ \bm{U}(\bm{U - U'}\mathcal{O})^{\top} \bm{U} ( \bm{U - U'}\mathcal{O})^{\top} \big] \geq 0,
    \end{align}
    where the inequality follows from Lemma 35 of \citet{ma_implicit_2020}, which states that the matrix $\bm{U}(\bm{U} - \bm{U}' \mathcal{O})^{\top}$ is a symmetric matrix.  Combining all of these bounds we obtain
    \begin{align}
