\end{align}
Then since
\begin{align}
    \frac{d}{dt^2} J(t) &= ( \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}} - \bm{U} )^{\top} \nabla^2 h(  \bm{U} + t ( \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}} - \bm{U})( \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}} - \bm{U} ) \geq \gamma \|  \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}} - \bm{U}\|_F^2,
\end{align}
it holds that $J(t)$ is strongly convex with parameter $\gamma \| \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}} - \bm{U} \|_F^2$.

Let $\bm{U}_0$ be any minimizer of $h(\cdot)$ within $\mathbb{B}(\bm{\widehat U},K)$. Then the condition of the lemma implies that $h(\bm{\widehat U}) \leq h(\bm{U}_0) + \ensuremath{\varepsilon}$.   Applying the argument above with $\bm{U} = \bm{U}_0$ implies that for any $s \in [0,1]$,
\begin{align}
    J(s t_1 + (1- s) t_2 ) &\leq s J(t_1) + (1- s) J(t_2) - \frac{1}{2} \gamma s(1-s) | t_1 - t_2|^2   \|  \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}_0} - \bm{U}^* \|_F^2 \\
    \Longrightarrow h( \bm{U}^* + s ( \bm{\widehat U} \mathcal{O}_{\bm{\widehat U},\bm{U}_0} - \bm{U}_0 )) &\leq s h( \bm{\widehat U} \mathcal{O}) + (1-s) h(\bm{U}_0) - \frac{1}{2} \gamma s(1-s)   \|  \bm{\widehat U} \mathcal{O} - \bm{U}_0 \|_F^2 \\
