    &\quad + 2\tau(\bm{U})^{-1} \frac{\|\bm{g}\|}{\sqrt{n}} \frac{d}{dt} \bigg\langle \bigg(  \frac{\big(\bm{UU}^{\top} + t \bm{VU}^{\top} + t \bm{UV}^{\top} + t^2 \bm{XX}^{\top}\big) - \bm{M} - \bm{H}}{n}  \bigg)\big( \bm{U} + t \bm{V} \big), \bm{V} \bigg \rangle \bigg|_{t=0} \\
    &= 2\frac{\|\bm{g}\|}{\sqrt{n}} \bigg\langle \bigg(\frac{ \bm{UU}^{\top}  - \bm{M}- \bm{H}}{n}  \bigg)  \bm{U}  , \bm{V} \bigg \rangle \frac{d}{dt} \tau(\bm{U} + t \bm{V})^{-1} \bigg|_{t=0} \\
    &\quad + 2\tau(\bm{U})^{-1} \frac{\|\bm{g}\|}{\sqrt{n}}  \bigg\langle \bigg(  \frac{\big(  \bm{VU}^{\top} +  \bm{UV}^{\top} \big) }{n}  \bigg)\bm{U}, \bm{V} \bigg \rangle \\
