 \label{lem:netargument}
Let $\{\bm{X}_i\}_{i=1}^{n} \sim {\sf GOE}(d)$, and let $\mathcal{X}(\cdot)$ be the operator that assigns entries $\mathcal{X}(\cdot)_i = \frac{1}{\sqrt{n}} \langle \bm{X}_i, \cdot\rangle $.  Then it holds that 
\begin{align}
  \sup_{\bm{V}  \in \mathbb{R}^{d \times r}:  \|\bm{V} \| \leq 1 }  \bigg\| \big( \mathcal{X}^* \mathcal{X} - \mathcal{I} \big) \big( \bm{VV}^{\top} \big) \bigg\| \lesssim \frac{ r\sqrt{d}}{\sqrt{n}} 
\end{align}
with probability at least $1 - 2 \exp ( - C_1 dr) - 2 \exp( - C_2 n )$.

We will proceed via $\ensuremath{\varepsilon}$-net argument.  First, let $\bm{V}$ be any fixed $d \times r$  orthonormal matrix.  We have that
\begin{align}
\mathcal{X}^* \mathcal{X} \big( \bm{V} \bm{V}^{\top} \big) &= 
    \frac{1}{n} \sum_{i=1}^{n} \bigg \langle \bm{X}_i, \bm{V} \bm{V}^{\top} \bigg\rangle\bm{X}_i \bm{V} \bm{V}^{\top}  \\
    &= \frac{1}{n} \sum_{i=1}^{n} \bigg \langle \bm{X}_i, \bm{V} \bm{V}^{\top} \bigg \rangle  \bigg( \bm{I} - \bm{V} \bm{V}^{\top} \bigg) \bm{X}_i \bm{V} \bm{V}^{\top} \\
    &\quad + \frac{1}{n} \sum_{i=1}^{n} \bigg \langle \bm{X}_i, \bm{V} \bm{V}^{\top} \bigg \rangle   \bm{V} \bm{V}^{\top}  \bm{X}_i \bm{V} \bm{V}^{\top} \\
    &= \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \bigg( \bm{V}^{\top} \bm{X}_i \bm{V} \bigg) \bigg( \bm{I} - \bm{V}\bm{V}^{\top} \bigg) \bm{X}_i \bm{V} \bm{V}^{\top} \\
    &\quad + \frac{1}{n} \sum_{i=1}^{n} {\sf Tr}  \bigg( \bm{V}^{\top} \bm{X}_i \bm{V} \bigg)  \bm{V} \bm{V}^{\top} \bm{X}_i \bm{V} \bm{V}^{\top}
\end{align}
As a result,
\begin{align}
\bigg\|    \bigg( \mathcal{X}^* \mathcal{X} - \mathcal{I} \bigg) \big( \bm{V} \bm{V}^{\top} \big) \bigg\| &\leq \bigg\| \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \bigg( \bm{V}^{\top} \bm{X}_i \bm{V} \bigg) \bigg( \bm{I} - \bm{V} \bm{V}^{\top} \bigg) \bm{X}_i \bm{V} \bigg\| \\
&\qquad +  \bigg\|\bm{V} -  \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \bigg( \bm{V}^{\top} \bm{X}_i \bm{V} \bigg)\bm{V} \bm{V}^{\top} \bm{X}_i \bm{V}  \bigg\| \\
:&= T_1 + T_2,
\end{align}
where we have used the rotational invariance of $\|\cdot\|$.  We analyze each term in turn. 
\begin{itemize}
    \item \textbf{The quantity $T_1$:}  By rotational invariance the quantities $\bm{V}^{\top} \bm{X}_i \bm{V}$ and $(\bm{I - VV}^{\top}) \bm{X}_i \bm{V } $ are  independent from each other, and hence each quantity inside the summation is a product of two independent random variables. Let $\bm{V}_{\perp}$ denote the $d \times (d-r) $ matrix such that $\bm{V}_{\perp}^{\top} \bm{V} = 0$, and let $c_i = {\sf Tr}\big( \bm{V}^{\top} \bm{X}_i \bm{V} \big)$.  We may then write the summation as
    \begin{align}
        \frac{1}{n} \sum_{i=1}^{n} c_i \bm{V}_{\perp } \bm{V}_{\perp}^{\top} \bm{X}_i \bm{V} &\overset{d}{=} \frac{1}{n} \sum_{i=1}^{n} c_i \bm{V}_{\perp } \bm{H}_i,
    \end{align}
    where $\bm{H}_i \in \mathbb{R}^{d-r \times r}$ is a matrix with $\mathcal{N}(0,1)$ entries. Furthermore, we have that
    \begin{align}
        \bigg\| \frac{1}{n} \sum_{i=1}^{n} c_i \bm{V}_{\perp} \bm{H}_i \bigg\| &\leq \bigg\| \frac{1}{n} \sum_{i=1}^{n} c_i \bm{H}_i \bigg\|.
    \end{align}
    So it suffices to bound the term above.  To do so, we proceed via $\ensuremath{\varepsilon}$-net.  let $\bm{x}, \bm{y}$ be $d-$dimensional and $r$-dimensional unit vectors respectively.  Then it holds that conditional on $\bm{x}^{\top} \bm{H}_i \bm{y}$, 
    \begin{align}
        \frac{1}{n} \sum_{i=1}^{n} c_i \bm{x}^{\top} \bm{H}_i \bm{y} \sim \mathcal{N} \bigg( 0, \frac{r}{n^2} \sum_{i=1}^{n} \big(\bm{x}^{\top} \bm{H}_i \bm{y} \big)^2 \bigg).
    \end{align}
    As a result, Hoeffding's inequality implies that with probability at least $1 - 2\exp(-c t^2)$,
    \begin{align}
        \bigg| \frac{1}{n}  \sum_{i=1}^{n} c_i \bm{x}^{\top} \bm{H}_i \bm{y} \bigg| &\lesssim t \frac{\sqrt{r}}{n} \sqrt{\sum_{i=1}^{n} \big( \bm{x}^{\top} \bm{H}_i \bm{y} \big)^2 }.
    \end{align}
    In addition, note that $\sqrt{\sum_{i=1}^{n} \big( \bm{x}^{\top} \bm{H}_i \bm{y} \big)^2 }$ is simply the norm of a standard Gaussian random variable in $n$-dimensions. Let the event $\mathcal{E}$ be denoted
    \begin{align}
        \mathcal{E} := \bigg\{ \sqrt{\sum_{i=1}^{n} \big( \bm{x}^{\top} \bm{H}_i \bm{y} \big)^2 } &\lesssim \sqrt{n} \bigg\}.
    \end{align}
    Then $\mathcal{E}$ holds with probability at least $1 -2 \exp( - c n)$.  Conditional on $\mathcal{E}$, with probability at least $1 - 2 \exp(- c t^2) $,
    \begin{align}
         \bigg| \frac{1}{n}  \sum_{i=1}^{n} c_i \bm{x}^{\top} \bm{H}_i \bm{y} \bigg| &\lesssim t \frac{\sqrt{r}}{\sqrt{n}} 
    \end{align}
    By taking the supremum over a $1/4$-net, we have that by redefining $t = C( \sqrt{d} + t )$, 
    \begin{align}
        \bigg\| \frac{1}{n} \sum_{i=1}^{n} c_i \bm{H}_i \bigg\| &\lesssim  \sqrt{\frac{r}{n}} \bigg( \sqrt{d} + t \bigg)
    \end{align}
    with probability at least $1 - 2 \exp( - c d t^2) - 2 \exp( C_1 d - c n )$.  Under the assumption $n \gg dr$, this probability is at least $1 - 2 \exp( -c d t^2) - 2 \exp( -c n)$.    
    \item \textbf{The quantity $T_2$:} We note that $\mathbb{E} \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \big( \bm{V}^{\top} \bm{X}_i \bm{V} \big) \bm{VV}^{\top} \bm{X}_i \bm{V} = \bm{VV}^{\top}$.  Let $\bm{\widetilde H}_i$ denote the random variable $\bm{V}^{\top} \bm{X}_i \bm{V}$.  Then $\bm{\widetilde H}_i$ is equal in distributionn to an $r\times r$ GOE random matrix.  We have that
    \begin{align}
        \bm{V} - \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \big( \bm{V}^{\top} \bm{X}_i \bm{V} \big) \bm{VV}^{\top} \bm{X}_i \bm{V}  &\overset{d}{=} \bm{V} -  \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \big( \bm{\widetilde H}_i \big) \bm{V} \bm{\widetilde H}_i \\
        &= \bm{V} \bigg( \bm{I} -   \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \big( \bm{\widetilde H}_i \big)  \bm{\widetilde H}_i \bigg).
    \end{align}
    Consequently,
    \begin{align}
        \| \bm{V} \bigg( \bm{I} -   \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \big( \bm{\widetilde H}_i \big)  \bm{\widetilde H}_i \bigg) \big\| &\leq \| \bm{I} - \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \big( \bm{\widetilde H}_i \big)  \bm{\widetilde H}_i \|,
    \end{align}
    since $\|\bm{V} \| = 1$.  Let $\bm{x}$ by any fixed $r$-dimensional unit vector.  Then
    \begin{align}
       \bm{x}^{\top} \bigg( \bm{I} - \frac{1}{n} \sum_{i=1}^{n} {\sf Tr} \big( \bm{\widetilde H}_i \big)  \bm{\widetilde H}_i  \bigg) \bm{x} &= \frac{1}{n} \sum_{i=1}^{n} \sum_{l=1}^{r} x_l^2 \bigg( (\bm{\widetilde H}_i)_{ll}^2 - 1 \bigg) + \frac{1}{n} \sum_{i=1}^{n} \sum_{l=1}^r \sum_{j \neq l} x_j^2 \big( \bm{\widetilde H}_i \big)_{ll} \big( \bm{\widetilde H}_i \big)_{jj} \\
       &\quad + \frac{1}{n} \sum_{i=1}^{n} \sum_{l=1}^{r} \sum_{j < k,j\neq l} 2 \big( \bm{\widetilde H}_i \big)_{ll} \big( \bm{\widetilde H}_i \big)_{jk} \bm{x}_j \bm{x}_k \\
       &=: J_1 + J_2 + J_3.
    \end{align}
We bound each of these quantities separately.
\begin{itemize}
    \item \textbf{The term $J_1$:} We note that $J_1$ is simply a sum of $nr$ independent rescaled $\chi^2$ random variables.   By Lemma 1 of \citet{laurent_adaptive_2000} it holds that
    \begin{align}
        J_1 \leq 2\frac{\sqrt{\sum_{l=1}^{r} x_l^4}}{n} t + 4\frac{r}{n} t^2 \leq 2 \frac{t}{n} + 4 \frac{r}{n} t^2 
    \end{align}
    with probability at least $1 - \exp(- t^2)$. 
    \item \textbf{The term $J_2$:} Note that we can write
    \begin{align*}
        J_2 &= \sum_{\substack{j=1,l=1\\j\neq l}}^r \bm{A}_{lj} \langle \bm{\widetilde H}_l, \bm{\widetilde H}_j \rangle,
    \end{align*}
    where $\bm{\widetilde H}_l$ is the $n$-dimensional vector with coordinates given by $(\bm{\widetilde H}_i)_{ll}$, and $\bm{A}_{lj} = \frac{x_j^2}{n}$.
Note that $\bm{A}$ is the matrix whose rows are all given by $[\frac{x_1^2}{n}, \frac{x_2^2}{n} \cdots \frac{x_r^2}{n} ]$.  It is then evident that $\|\bm{A}\| = \frac{1}{n}$ and 
 \begin{align*}
     \| \bm{A} \|_F^2 &= r \sum_j \frac{x_j^4}{n^2} \leq \frac{r}{n^2}.
 \end{align*}
        By Proposition 2.5 of \citet{chen_hansonwright_2021}, it holds that
    \begin{align*}
        \mathbb{P}\big\{ | J_2 | > C t \big\} &\leq 2\exp\bigg( - C n\min\bigg[ \frac{ t^2}{r}, t \bigg] \bigg).
    \end{align*}
Redefining $t =  t \sqrt{\frac{r}{n}}$, we obtain that
    \begin{align}
        |J_2| \leq C t \sqrt{\frac{r}{n}}
    \end{align}
    with probability at least  $1 - 2 \exp( - c t^2)$ for all $t \leq \sqrt{nr}$.  
    \item \textbf{The term $J_3$:} We note that
\begin{align}
J_3 &= \frac{1}{n} \sum_{i=1}^n \sum_{l=1}^{r} 2 \big( \bm{\widetilde H}_i \big)_{ll} \sum_{j < k,j\neq l} \big( \bm{\widetilde H}_i \big)_{jk} \bm{x}_j \bm{x}_k \\
&= \frac{1}{n} \sum_{i=1}^{n} \sum_{j < k, j \neq l} 2 \big( \bm{\widetilde H}_i \big)_{jk} x_j x_k y_i,
\end{align}
where $y_i =  \sum_{l=1}^{r} \big( \bm{\widetilde H}_i \big)_{ll}.$  Conditional on $y$, Hoeffding's inequality implies that with probability at least $1 - 2 \exp( - c t^2)$, 
\begin{align*}
\bigg| \frac{1}{n} \sum_{i=1}^{n} \sum_{j < k, j \neq l} 2 \big( \bm{\widetilde H}_i \big)_{jk} x_j x_k y_i \bigg| \leq t \frac{C}{n} \sqrt{\sum_{i=1}^{n} y_i^2}.
\end{align*}
Observe that each $y_i$ is a Gaussian random variable with variance $r$.  Consequently, with probability at least $1 - 2\exp( - c n) - 2 \exp( - C  t^2) $ it holds that 
\begin{align*}
    t \frac{C}{n} \sqrt{\sum_{i=1}^{n} y_i^2} \leq C \frac{t \sqrt{r}}{\sqrt{n}}.
\end{align*}
\end{itemize}
Combining all these bounds, we obtain that with probability at least $1 - O\bigg(   \exp( - c t^2) - 2 \exp( - c n) \bigg)$ for all $t \leq \sqrt{nr}$,
\begin{align*}
    |J_1 | + |J_2| + |J_3| \lesssim t \sqrt{\frac{r}{n}} + \frac{t}{n} +  \frac{r}{n} t^2 
\end{align*}
Define $t = C ( \sqrt{r} + s)$.  Then a net argument shows that for all $s \leq c \sqrt{nr}$,
\begin{align}
    |J_1| + |J_2| + |J_3| \lesssim ( \sqrt{r} + s ) \sqrt{\frac{r}{n}} + \frac{\sqrt{r}  + s }{n} + \frac{r}{n} ( r + s^2),
\end{align}
which holds with probability at least
\begin{align*}
    1 - \exp ( - c s ^2) - 2 \exp( - c n),
